import subprocess, os, re
EX=os.path.realpath("./executable")
def fmt_of(size, fmt):
    path="/tmp/fmt/f"
    try:
        with open(path,"wb") as fh: fh.truncate(size)
    except Exception as e:
        print("trunc fail",size,e); return None
    p=subprocess.run([EX,"-A","-f",fmt,"aggregate",path], capture_output=True, text=True)
    out=re.sub(r'\x1b\[[0-9;]*m','',p.stdout).rstrip("\n")
    return out.rsplit(" /tmp",1)[0]
for fmt in ["binary","metric"]:
    print(fmt)
    for exp in range(0,7):
        base=(1024 if fmt=="binary" else 1000)**exp
        for delta in [-1,0,1]:
            s=base+delta
            if s<0: continue
            print(exp, s, fmt_of(s,fmt))
    for s in [1024**6, 1024**6+1, 5*1024**6, 1024**7 if False else 0]:
        if s: print(s, fmt_of(s,fmt))
# rounding edge: find value where x.xx5 rounding
for s in [1126,1127,1177,1178,1228,1229]: # 1.099 KiB etc
    print(s, fmt_of(s,"binary"))
PY
