{"command":"cat > /tmp/tui_compact.py <<'PY'
import sys; sys.path.insert(0,"/tmp")
import tui
orig_cap=tui.cap
def compact():
    s=orig_cap(False)
    lines=[]
    for ln in s.splitlines():
        stripped=ln.strip(' │║█')
        # Keep all non-blank box lines; also keep first/last structural lines
        if stripped=='':
            continue
        lines.append(ln.rstrip())
    return "\n".join(lines)+"\n"
# Monkey patch print calls? We'll use functions manually here
def start(cmd,w=80,h=24,cwd=None): tui.start(cmd,w,h,cwd); init()
def init(label="INIT"): print(f"\n=== {label} ==="); print(compact(),end=""); print(f"[alive={tui.tmux('list-panes','-t',tui.SESS).returncode==0}]")
def act(key,label="",wait=.3,literal=False):
    if literal: tui.tmux("send-keys","-t",tui.SESS,"-l",key)
    else: tui.tmux("send-keys","-t",tui.SESS,key)
    import time; time.sleep(wait)
    print(f"\n=== {key!r} {label} ==="); print(compact(),end=""); print(f"[alive={tui.tmux('list-panes','-t',tui.SESS).returncode==0}]")
def end(): tui.end()
def capesc(): return orig_cap(True)
PY
