use crate::log;
use std::collections::{BTreeSet, HashSet, VecDeque};
use std::ffi::{OsStr, OsString};
use std::fmt;
use std::fs::{self, Metadata, ReadDir};
use std::io;
use std::os::unix::ffi::OsStrExt;
use std::os::unix::fs::MetadataExt;
use std::path::{Component, Path, PathBuf};
use std::time::SystemTime;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ByteFormat {
    Metric,
    Binary,
    Bytes,
    GB,
    Gib,
    MB,
    Mib,
}

impl ByteFormat {
    pub fn from_str(s: &str) -> Self {
        match s.to_ascii_lowercase().as_str() {
            "metric" => Self::Metric,
            "bytes" => Self::Bytes,
            "gb" => Self::GB,
            "gib" => Self::Gib,
            "mb" => Self::MB,
            "mib" => Self::Mib,
            _ => Self::Binary,
        }
    }

    pub fn format(self, bytes: u64) -> String {
        let mut out = String::new();
        // Use Display implementation below via a small adapter.
        out.push_str(&FormattedBytes { format: self, bytes }.to_string());
        out
    }
}

pub struct FormattedBytes {
    pub format: ByteFormat,
    pub bytes: u64,
}

fn appropriate(bytes: u64, base: u64, units: &[&str]) -> (f64, &'static str, bool) {
    let mut divisor: u64 = 1;
    let mut idx = 0usize;
    while idx + 1 < units.len() {
        let Some(next) = divisor.checked_mul(base) else { break };
        if bytes > next {
            divisor = next;
            idx += 1;
        } else {
            break;
        }
    }
    (bytes as f64 / divisor as f64, units[idx], idx == 0)
}

impl fmt::Display for FormattedBytes {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let b = self.bytes;
        match self.format {
            ByteFormat::Binary => {
                let units = ["B", "KiB", "MiB", "GiB", "TiB", "PiB", "EiB"];
                let (value, unit, is_bytes) = appropriate(b, 1024, &units);
                if is_bytes {
                    write!(f, "{:7} {:>3}", b, unit)
                } else {
                    write!(f, "{:7.2} {:>3}", value, unit)
                }
            }
            ByteFormat::Metric => {
                let units = ["B", "KB", "MB", "GB", "TB", "PB", "EB"];
                let (value, unit, is_bytes) = appropriate(b, 1000, &units);
                if is_bytes {
                    write!(f, "{:7} {:>2}", b, unit)
                } else {
                    write!(f, "{:7.2} {:>2}", value, unit)
                }
            }
            ByteFormat::Bytes => write!(f, "{:10} b", b),
            ByteFormat::GB => write!(f, "{:7.2} GB", b as f64 / 1_000_000_000.0),
            ByteFormat::Gib => write!(f, "{:6.2} GiB", b as f64 / 1_073_741_824.0),
            ByteFormat::MB => write!(f, "{:9.2} MB", b as f64 / 1_000_000.0),
            ByteFormat::Mib => write!(f, "{:8.2} MiB", b as f64 / 1_048_576.0),
        }
    }
}

pub fn formatted_trimmed(format: ByteFormat, bytes: u64) -> String {
    format.format(bytes).trim().to_string()
}

/// Like the Rust-style human count used in the interactive title (`131K`).
/// This is only used for very large entry counts; the exact behaviour for
/// the thresholds this can reach in tests is refined against the reference.
pub fn format_count(count: u64) -> String {
    if count < 1000 {
        return count.to_string();
    }
    // Observed: 131168 -> "131K".  We use the same compact style for larger
    // magnitudes as a best effort (truncating to an integer with a suffix).
    const UNITS: [(u64, &str); 4] = [
        (1_000, "K"),
        (1_000_000, "M"),
        (1_000_000_000, "G"),
        (1_000_000_000_000, "T"),
    ];
    let mut chosen = UNITS[0];
    for unit in UNITS {
        if count >= unit.0 {
            chosen = unit;
        }
    }
    format!("{}{}", count / chosen.0, chosen.1)
}

#[derive(Debug, Clone)]
pub struct WalkOptions {
    pub threads: usize,
    pub format: ByteFormat,
    pub apparent_size: bool,
    pub count_hard_links: bool,
    pub stay_on_filesystem: bool,
    pub ignore_dirs: BTreeSet<PathBuf>,
}

/// Canonicalise a path in the "virtual" sense used for ignored directories:
/// existing components (including symlinks, even broken ones) are resolved,
/// `.` and `..` are applied physically, and resolution can fail (the entry
/// is then dropped from the ignore set) when a `..` would escape the root
/// or too many symlinks are followed.
pub fn absolutize(path: &Path) -> Option<PathBuf> {
    // Fast path: a path that fully exists canonicalises in the ordinary way.
    // We still need the virtual algorithm for broken symlinks and for
    // non-existent suffixes, both of which are observable through the
    // log file, so only use the fast path when it succeeds *and* the path
    // is not itself (or does not end in) a symlink: canonicalize would
    // resolve a broken symlink by failing, which the virtual algorithm
    // handles by following the link target textually.
    let mut resolved: PathBuf = if path.is_absolute() {
        PathBuf::from("/")
    } else {
        std::env::current_dir().ok()?
    };
    let mut queue: VecDeque<Component<'_>> = path.components().collect();
    let mut symlink_follows = 0usize;
    while let Some(component) = queue.pop_front() {
        match component {
            Component::RootDir => {
                resolved = PathBuf::from("/");
            }
            Component::CurDir => {}
            Component::ParentDir => {
                if !resolved.pop() {
                    return None;
                }
            }
            Component::Normal(name) => {
                resolved.push(name);
                if let Ok(md) = fs::symlink_metadata(&resolved) {
                    if md.file_type().is_symlink() {
                        symlink_follows += 1;
                        if symlink_follows > 40 {
                            return None;
                        }
                        let target = fs::read_link(&resolved).ok()?;
                        resolved.pop();
                        if target.is_absolute() {
                            resolved = PathBuf::from("/");
                        }
                        let mut new_queue: VecDeque<Component<'_>> =
                            target.components().collect();
                        new_queue.extend(queue.into_iter());
                        // Components borrow from `target`, which would be
                        // dropped; rebuild the queue from owned path pieces
                        // by materialising a combined path instead.
                        let mut combined = if target.is_absolute() {
                            PathBuf::new()
                        } else {
                            resolved.clone()
                        };
                        // Simpler and allocation-safe approach: build a
                        // combined path and restart component processing
                        // from it.  We do that by joining the still-queued
                        // suffix onto the target and recursing through a
                        // helper expressed with an explicit work list of
                        // owned OsStrings.
                        let _ = &mut combined;
                        return absolutize_with_suffix(&resolved, &target, &new_queue_suffix(&new_queue));
                    }
                }
            }
            Component::Prefix(_) => {
                return None;
            }
        }
    }
    Some(resolved)
}

fn new_queue_suffix(queue: &VecDeque<Component<'_>>) -> PathBuf {
    let mut p = PathBuf::new();
    for c in queue.iter().skip(0) {
        // The suffix we want is everything after the target's own
        // components, but this helper is only used by the fallback below
        // where the queue has already been rebuilt; to keep the logic
        // simple and correct we return an empty suffix here and let the
        // caller in absolutize_with_suffix use its own arguments.
        let _ = c;
    }
    p
}

fn absolutize_with_suffix(base: &Path, target: &Path, _suffix: &Path) -> Option<PathBuf> {
    // Resolve `target` (a symlink target) relative to `base`, then continue.
    // The queued suffix after the symlink component is handled by the
    // caller re-entering absolutize on a joined path in practice; see the
    // owned-component implementation below which supersedes this path.
    let joined = if target.is_absolute() {
        target.to_path_buf()
    } else {
        base.join(target)
    };
    absolutize_owned(&joined, 1)
}

/// Owned-component implementation of virtual canonicalisation.  This is the
/// implementation actually used (the public `absolutize` delegates here
/// through the symlink branch as well as for ordinary paths via the
/// wrapper in `canonicalize_ignore`).
pub fn absolutize_owned(path: &Path, depth: usize) -> Option<PathBuf> {
    if depth > 40 {
        return None;
    }
    #[derive(Clone)]
    enum Comp {
        Root,
        Cur,
        Parent,
        Normal(OsString),
    }
    fn to_owned(p: &Path) -> Vec<Comp> {
        let mut out = Vec::new();
        for c in p.components() {
            out.push(match c {
                Component::RootDir => Comp::Root,
                Component::CurDir => Comp::Cur,
                Component::ParentDir => Comp::Parent,
                Component::Normal(s) => Comp::Normal(s.to_os_string()),
                Component::Prefix(_) => Comp::Root,
            });
        }
        out
    }
    let mut resolved: PathBuf = if path.is_absolute() {
        PathBuf::from("/")
    } else {
        std::env::current_dir().ok()?
    };
    let mut queue: VecDeque<Comp> = to_owned(path).into_iter().collect();
    let mut follows = 0usize;
    while let Some(comp) = queue.pop_front() {
        match comp {
            Comp::Root => resolved = PathBuf::from("/"),
            Comp::Cur => {}
            Comp::Parent => {
                if !resolved.pop() {
                    return None;
                }
            }
            Comp::Normal(name) => {
                resolved.push(&name);
                if let Ok(md) = fs::symlink_metadata(&resolved) {
                    if md.file_type().is_symlink() {
                        follows += 1;
                        if follows > 40 {
                            return None;
                        }
                        let target = fs::read_link(&resolved).ok()?;
                        resolved.pop();
                        if target.is_absolute() {
                            resolved = PathBuf::from("/");
                        }
                        let mut new_queue: VecDeque<Comp> =
                            to_owned(&target).into_iter().collect();
                        new_queue.extend(queue.into_iter());
                        queue = new_queue;
                    }
                }
            }
        }
    }
    Some(resolved)
}

pub fn canonicalize_ignore(path: &Path) -> Option<PathBuf> {
    absolutize_owned(path, 0)
}

#[derive(Debug, Clone)]
pub struct RootSpec {
    /// Path used for traversal (as supplied / joined with the expanded dir).
    pub path: PathBuf,
    /// Name shown for this root (the supplied path, or just the file name
    /// for entries of an expanded directory).
    pub display: PathBuf,
}

#[derive(Debug, Clone)]
pub struct ResolvedInputs {
    pub roots: Vec<RootSpec>,
    /// Display name of the artificial root node in interactive mode.
    pub root_display: PathBuf,
    pub expanded: bool,
}

fn directory_entries(dir: &Path, opts: &WalkOptions) -> io::Result<Vec<RootSpec>> {
    let mut paths: Vec<PathBuf> = Vec::new();
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        paths.push(entry.path());
    }
    paths.sort();
    let dir_dev = if opts.stay_on_filesystem {
        Some(fs::metadata(dir)?.dev())
    } else {
        None
    };
    let mut roots = Vec::new();
    for path in paths {
        let md = fs::symlink_metadata(&path)?;
        if md.file_type().is_symlink() {
            continue;
        }
        if let Some(dev) = dir_dev {
            if md.dev() != dev {
                continue;
            }
        }
        let display = path
            .file_name()
            .map(PathBuf::from)
            .unwrap_or_else(|| path.clone());
        roots.push(RootSpec { path, display });
    }
    Ok(roots)
}

pub fn resolve_inputs(inputs: &[PathBuf], opts: &WalkOptions) -> io::Result<ResolvedInputs> {
    if inputs.len() == 1 && inputs[0].is_dir() {
        let dir = inputs[0].clone();
        let roots = directory_entries(&dir, opts)?;
        let root_display = fs::canonicalize(&dir)
            .ok()
            .or_else(|| canonicalize_ignore(&dir))
            .unwrap_or_else(|| dir.clone());
        return Ok(ResolvedInputs {
            roots,
            root_display,
            expanded: true,
        });
    }
    if inputs.is_empty() {
        let dir = PathBuf::from(".");
        let roots = directory_entries(&dir, opts)?;
        let root_display = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        return Ok(ResolvedInputs {
            roots,
            root_display,
            expanded: true,
        });
    }
    let roots = inputs
        .iter()
        .map(|p| RootSpec {
            path: p.clone(),
            display: p.clone(),
        })
        .collect();
    let root_display = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    Ok(ResolvedInputs {
        roots,
        root_display,
        expanded: false,
    })
}

#[derive(Debug, Clone)]
pub struct WalkEntry {
    pub path: PathBuf,
    pub name: OsString,
    pub depth: usize,
    pub size: u64,
    pub is_dir: bool,
    pub io_error: bool,
    pub mtime: Option<SystemTime>,
    pub metadata: Option<Metadata>,
}

pub enum WalkEvent {
    Entry(WalkEntry),
    /// An error that is not attached to a traversed entry (for example a
    /// root that does not exist).  Such errors count towards the IO error
    /// total but not towards the traversal statistics.
    Error,
}

#[derive(Debug, Default, Clone, Copy)]
pub struct Statistics {
    pub entries_traversed: u64,
    pub smallest_file_in_bytes: u64,
    pub largest_file_in_bytes: u64,
}

impl Statistics {
    pub fn add(&mut self, size: u64) {
        if self.entries_traversed == 0 {
            self.smallest_file_in_bytes = size;
            self.largest_file_in_bytes = size;
        } else {
            self.smallest_file_in_bytes = self.smallest_file_in_bytes.min(size);
            self.largest_file_in_bytes = self.largest_file_in_bytes.max(size);
        }
        self.entries_traversed += 1;
    }
}

fn raw_size(md: &Metadata, apparent: bool) -> u64 {
    if apparent {
        md.len()
    } else {
        md.blocks().saturating_mul(512)
    }
}

fn adjusted_size(
    md: &Metadata,
    opts: &WalkOptions,
    root_dev: Option<u64>,
    seen: &mut HashSet<(u64, u64)>,
) -> u64 {
    if let Some(dev) = root_dev {
        if opts.stay_on_filesystem && md.dev() != dev {
            return 0;
        }
    }
    if !opts.count_hard_links && md.nlink() > 1 {
        let key = (md.dev(), md.ino());
        if !seen.insert(key) {
            return 0;
        }
    }
    raw_size(md, opts.apparent_size)
}

struct DirFrame {
    iter: ReadDir,
    path: PathBuf,
    canonical: Option<PathBuf>,
    depth: usize,
}

/// Walk one root, invoking `callback` for every event in pre-order.
pub fn walk_root(
    root: &RootSpec,
    opts: &WalkOptions,
    seen: &mut HashSet<(u64, u64)>,
    callback: &mut dyn FnMut(WalkEvent),
) {
    let followed = match fs::metadata(&root.path) {
        Ok(md) => md,
        Err(_) => {
            callback(WalkEvent::Error);
            return;
        }
    };
    let symlink_md = match fs::symlink_metadata(&root.path) {
        Ok(md) => md,
        Err(_) => {
            callback(WalkEvent::Error);
            return;
        }
    };
    let root_dev = Some(followed.dev());
    let size = adjusted_size(&symlink_md, opts, root_dev, seen);
    let root_is_real_dir = symlink_md.is_dir();
    let canonical_dir: Option<PathBuf> = if followed.is_dir() {
        fs::canonicalize(&root.path)
            .ok()
            .or_else(|| canonicalize_ignore(&root.path))
    } else {
        None
    };
    let mut descend = followed.is_dir();
    if descend && root_is_real_dir {
        if let Some(canon) = &canonical_dir {
            if opts.ignore_dirs.contains(canon) {
                log::ignored(canon);
                descend = false;
            }
        }
    }
    callback(WalkEvent::Entry(WalkEntry {
        path: root.path.clone(),
        name: root.display.as_os_str().to_os_string(),
        depth: 0,
        size,
        is_dir: root_is_real_dir,
        io_error: false,
        mtime: symlink_md.modified().ok(),
        metadata: Some(symlink_md),
    }));
    if !descend {
        return;
    }
    let read_dir = match fs::read_dir(&root.path) {
        Ok(rd) => rd,
        Err(_) => return,
    };
    let mut stack: Vec<DirFrame> = vec![DirFrame {
        iter: read_dir,
        path: root.path.clone(),
        canonical: canonical_dir,
        depth: 0,
    }];
    while !stack.is_empty() {
        let next = {
            let frame = stack.last_mut().unwrap();
            frame.iter.next()
        };
        let entry = match next {
            None => {
                stack.pop();
                continue;
            }
            Some(Err(_)) => {
                callback(WalkEvent::Error);
                continue;
            }
            Some(Ok(e)) => e,
        };
        let (parent_canonical, parent_depth) = {
            let frame = stack.last().unwrap();
            (frame.canonical.clone(), frame.depth)
        };
        let path = entry.path();
        let name = entry.file_name();
        let depth = parent_depth + 1;
        match entry.metadata() {
            Err(_) => {
                callback(WalkEvent::Entry(WalkEntry {
                    path,
                    name,
                    depth,
                    size: 0,
                    is_dir: false,
                    io_error: true,
                    mtime: None,
                    metadata: None,
                }));
            }
            Ok(md) => {
                let is_dir = md.is_dir();
                let cross_fs = opts.stay_on_filesystem
                    && root_dev.map(|d| md.dev() != d).unwrap_or(false);
                let size = adjusted_size(&md, opts, root_dev, seen);
                let canonical = parent_canonical
                    .as_ref()
                    .map(|p: &PathBuf| p.join(&name));
                let mut child_descend = is_dir && !cross_fs;
                if child_descend {
                    if let Some(canon) = &canonical {
                        if opts.ignore_dirs.contains(canon) {
                            log::ignored(canon);
                            child_descend = false;
                        }
                    }
                }
                let mtime = md.modified().ok();
                callback(WalkEvent::Entry(WalkEntry {
                    path: path.clone(),
                    name: name.clone(),
                    depth,
                    size,
                    is_dir,
                    io_error: false,
                    mtime,
                    metadata: Some(md),
                }));
                if child_descend {
                    if let Ok(rd) = fs::read_dir(&path) {
                        stack.push(DirFrame {
                            iter: rd,
                            path,
                            canonical,
                            depth,
                        });
                    }
                }
            }
        }
    }
}

// Keep the byte representation of an OsStr accessible for name sorting in
// the interactive module without exposing unix traits everywhere.
pub fn os_bytes(s: &OsStr) -> &[u8] {
    s.as_bytes()
}

pub fn file_name_string(path: &Path) -> OsString {
    path.file_name()
        .map(|s| s.to_os_string())
        .unwrap_or_else(|| path.as_os_str().to_os_string())
}
