    actual: PathBuf,
    size: u64,
    num_errors: u64,
}

fn write_path<W: Write>(
    out: &mut W,
    format: ByteFormat,
    size: u64,
    display: &Path,
    is_file: bool,
    num_errors: u64,
) -> io::Result<()> {
    write!(out, "\x1b[32m{}\x1b[39m ", format.format(size))?;
    if is_file {
        write!(out, "{}", display.display())?;
    } else {
        write!(out, "\x1b[36m{}\x1b[39m", display.display())?;
    }
    if num_errors > 0 {
        if num_errors == 1 {
            write!(out, "  <1 IO Error>")?;
        } else {
            write!(out, "  <{} IO Errors>", num_errors)?;
        }
    }
    writeln!(out)
}

pub fn run(
    inputs: &[PathBuf],
    walk_opts: &WalkOptions,
    options: AggregateOptions,
) -> io::Result<i32> {
    let resolved = resolve_inputs(inputs, walk_opts)?;
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    let mut seen: HashSet<(u64, u64)> = HashSet::new();
    let mut stats = Statistics::default();
    let mut total_size: u64 = 0;
    let mut total_errors: u64 = 0;
    let root_count = resolved.roots.len();

    if options.no_sort {
        for root in &resolved.roots {
            let mut data: Option<PathData> = None;
            let mut root_only_errors: u64 = 0;
            walk_root(root, walk_opts, &mut seen, &mut |event| match event {
                WalkEvent::Entry(entry) => {
                    stats.add(entry.size);
                    let pd = data.get_or_insert_with(|| PathData {
                        display: root.display.clone(),
                        actual: root.path.clone(),
                        size: 0,
                        num_errors: 0,
                    });
                    pd.size += entry.size;
                    if entry.io_error {
                        pd.num_errors += 1;
                    }
                }
                WalkEvent::Error => {
                    if let Some(pd) = data.as_mut() {
                        pd.num_errors += 1;
                    } else {
                        root_only_errors += 1;
                    }
                }
            });
            if let Some(pd) = data {
                write_path(
                    &mut out,
                    walk_opts.format,
                    pd.size,
                    &pd.display,
                    pd.actual.is_file(),
                    pd.num_errors,
                )?;
                total_size += pd.size;
                total_errors += pd.num_errors;
            }
            total_errors += root_only_errors;
        }
    } else {
        let mut paths: Vec<PathData> = Vec::new();
        for root in &resolved.roots {
            let mut pd = PathData {
                display: root.display.clone(),
                actual: root.path.clone(),
                size: 0,
                num_errors: 0,
            };
            walk_root(root, walk_opts, &mut seen, &mut |event| match event {
                WalkEvent::Entry(entry) => {
                    stats.add(entry.size);
                    pd.size += entry.size;
                    if entry.io_error {
                        pd.num_errors += 1;
                    }
                }
                WalkEvent::Error => {
                    pd.num_errors += 1;
                }
            });
            total_size += pd.size;
            total_errors += pd.num_errors;
            paths.push(pd);
        }
        paths.sort_by_key(|pd| pd.size);
        for pd in &paths {
            write_path(
                &mut out,
                walk_opts.format,
                pd.size,
                &pd.display,
                pd.actual.is_file(),
                pd.num_errors,
            )?;
        }
    }

    if !options.no_total && root_count > 1 {
        write_path(
            &mut out,
            walk_opts.format,
            total_size,
            Path::new("total"),
            true,
            total_errors,
        )?;
    }
    out.flush()?;

    if options.statistics {
        eprintln!("{:?}", stats);
    }
    Ok(if total_errors > 0 { 1 } else { 0 })
}
