mod aggregate;
mod common;
mod interactive;
mod log;

use clap::{value_parser, Arg, ArgAction, Command as ClapCommand};
use common::{canonicalize_ignore, ByteFormat, WalkOptions};
use std::collections::BTreeSet;
use std::error::Error;
use std::io::{self, IsTerminal, Write};
use std::path::PathBuf;
use std::process::ExitCode;

const INPUT_HELP: &str = "One or more input files or directories. If unset, we will use all entries in the current working directory";
const VERSION: &str = "2.32.2";

#[derive(Debug)]
#[allow(dead_code)]
struct Args {
    command: Option<Command>,
    threads: usize,
    format: ByteFormat,
    apparent_size: bool,
    count_hard_links: bool,
    stay_on_filesystem: bool,
    ignore_dirs: Vec<PathBuf>,
    input: Vec<PathBuf>,
    log_file: Option<PathBuf>,
}

#[derive(Debug)]
#[allow(dead_code)]
enum Command {
    Interactive {
        no_entry_check: bool,
        input: Vec<PathBuf>,
    },
    Aggregate {
        statistics: bool,
        no_sort: bool,
        no_total: bool,
        input: Vec<PathBuf>,
    },
    Completions {
        shell: clap_complete::Shell,
    },
}

fn input_arg() -> Arg {
    Arg::new("input")
        .value_name("INPUT")
        .help(INPUT_HELP)
        .action(ArgAction::Append)
        .num_args(0..)
        .value_parser(value_parser!(PathBuf))
}

fn build_command() -> ClapCommand {
    ClapCommand::new("dua")
        .version(VERSION)
        .about("A tool to learn about disk usage, fast!")
        .override_usage("dua [FLAGS] [OPTIONS] [SUBCOMMAND] [INPUT]...")
        .arg(input_arg().long_help(INPUT_HELP))
        .arg(
            Arg::new("threads")
                .short('t')
                .long("threads")
                .value_name("THREADS")
                .help("The amount of threads to use. Defaults to 0, indicating the amount of logical processors. Set to 1 to use only a single thread")
                .long_help("The amount of threads to use. Defaults to 0, indicating the amount of logical processors. Set to 1 to use only a single thread")
                .default_value("0")
                .value_parser(value_parser!(usize)),
        )
        .arg(
            Arg::new("format")
                .short('f')
                .long("format")
                .value_name("FORMAT")
                .help("The format with which to print byte counts")
                .long_help("The format with which to print byte counts")
                .default_value("binary")
                .value_parser(["metric", "binary", "bytes", "gb", "gib", "mb", "mib"])
                .ignore_case(true),
        )
        .arg(
            Arg::new("apparent_size")
                .short('A')
                .long("apparent-size")
                .help("Display apparent size instead of disk usage")
                .long_help("Display apparent size instead of disk usage")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("count_hard_links")
                .short('l')
                .long("count-hard-links")
                .help("Count hard-linked files each time they are seen")
                .long_help("Count hard-linked files each time they are seen")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("stay_on_filesystem")
                .short('x')
                .long("stay-on-filesystem")
                .help("If set, we will not cross filesystems or traverse mount points")
                .long_help("If set, we will not cross filesystems or traverse mount points")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("ignore_dirs")
                .short('i')
                .long("ignore-dirs")
                .value_name("IGNORE_DIRS")
                .help("One or more absolute directories to ignore. Note that these are not ignored if they are passed as input path")
                .long_help("One or more absolute directories to ignore. Note that these are not ignored if they are passed as input path.\n\nHence, they will only be ignored if they are eventually reached as part of the traversal.")
                .action(ArgAction::Append)
                .default_values(["/proc", "/dev", "/sys", "/run"])
                .value_parser(value_parser!(PathBuf)),
        )
        .arg(
            Arg::new("log_file")
                .long("log-file")
                .value_name("LOG_FILE")
                .help("Write a log file with debug information, including panics")
                .long_help("Write a log file with debug information, including panics")
                .value_parser(value_parser!(PathBuf)),
        )
        .subcommand(
            ClapCommand::new("interactive")
                .visible_alias("i")
                .about("Launch the terminal user interface")
                .arg(input_arg())
                .arg(
                    Arg::new("no_entry_check")
                        .short('e')
                        .long("no-entry-check")
                        .help("Do not check entries for presence when listing a directory to avoid slugging performance on slow filesystems")
                        .action(ArgAction::SetTrue),
                ),
        )
        .subcommand(
            ClapCommand::new("aggregate")
                .visible_alias("a")
                .about("Aggregate the consumed space of one or more directories or files")
                .arg(input_arg())
                .arg(
                    Arg::new("statistics")
                        .long("stats")
                        .help("If set, print additional statistics about the file traversal to stderr")
                        .action(ArgAction::SetTrue),
                )
                .arg(
                    Arg::new("no_sort")
                        .long("no-sort")
                        .help("If set, paths will be printed in their order of occurrence on the command-line. Otherwise they are sorted by their size in bytes, ascending")
                        .action(ArgAction::SetTrue),
                )
                .arg(
                    Arg::new("no_total")
                        .long("no-total")
                        .help("If set, no total column will be computed for multiple inputs")
                        .action(ArgAction::SetTrue),
                ),
        )
        .subcommand(
            ClapCommand::new("completions")
                .about("Generate shell completions")
                .arg(
                    Arg::new("shell")
                        .value_name("SHELL")
                        .required(true)
                        .help("The shell to generate a completions-script for")
                        .value_parser(["bash", "elvish", "fish", "powershell", "zsh"]),
                ),
        )
}

fn get_paths(matches: &clap::ArgMatches) -> Vec<PathBuf> {
    matches
        .get_many::<PathBuf>("input")
        .map(|values| values.cloned().collect())
        .unwrap_or_default()
}

fn parse_args(matches: &clap::ArgMatches) -> Args {
    let command = match matches.subcommand() {
        Some(("interactive", sub)) => Some(Command::Interactive {
            no_entry_check: sub.get_flag("no_entry_check"),
            input: get_paths(sub),
        }),
        Some(("aggregate", sub)) => Some(Command::Aggregate {
            statistics: sub.get_flag("statistics"),
            no_sort: sub.get_flag("no_sort"),
            no_total: sub.get_flag("no_total"),
            input: get_paths(sub),
        }),
        Some(("completions", sub)) => {
            let value = sub.get_one::<String>("shell").map(|s| s.as_str()).unwrap_or("bash");
            let shell = match value {
                "elvish" => clap_complete::Shell::Elvish,
                "fish" => clap_complete::Shell::Fish,
                "powershell" => clap_complete::Shell::PowerShell,
                "zsh" => clap_complete::Shell::Zsh,
                _ => clap_complete::Shell::Bash,
            };
            Some(Command::Completions { shell })
        }
        _ => None,
    };
    Args {
        command,
        threads: *matches.get_one::<usize>("threads").unwrap_or(&0),
        format: matches
            .get_one::<String>("format")
            .map(|s| ByteFormat::from_str(s))
            .unwrap_or(ByteFormat::Binary),
        apparent_size: matches.get_flag("apparent_size"),
        count_hard_links: matches.get_flag("count_hard_links"),
        stay_on_filesystem: matches.get_flag("stay_on_filesystem"),
        ignore_dirs: matches
            .get_many::<PathBuf>("ignore_dirs")
            .map(|values| values.cloned().collect())
            .unwrap_or_default(),
        input: if matches.subcommand_name().is_some() {
            Vec::new()
        } else {
            get_paths(matches)
        },
        log_file: matches.get_one::<PathBuf>("log_file").cloned(),
    }
}

fn run() -> Result<i32, Box<dyn Error>> {
    let matches = build_command().get_matches();
    let args = parse_args(&matches);

    if let Some(log_file) = &args.log_file {
        log::init(log_file)?;
    }
    log::info(&format!("dua options={:#?}", args));

    let ignore_dirs: BTreeSet<PathBuf> = args
        .ignore_dirs
        .iter()
        .filter_map(|path| canonicalize_ignore(path))
        .collect();
    log::info(&format!("Ignoring canonicalized {:?}", ignore_dirs));

    let walk_opts = WalkOptions {
        threads: args.threads,
        format: args.format,
        apparent_size: args.apparent_size,
        count_hard_links: args.count_hard_links,
        stay_on_filesystem: args.stay_on_filesystem,
        ignore_dirs,
    };

    let code = match &args.command {
        Some(Command::Completions { shell }) => {
            let mut buffer: Vec<u8> = Vec::new();
            let mut cmd = build_command();
            clap_complete::generate(*shell, &mut cmd, "dua", &mut buffer);
            let text = String::from_utf8_lossy(&buffer).replace("__subcmd", "");
            let stdout = io::stdout();
            let mut lock = stdout.lock();
            lock.write_all(text.as_bytes())?;
            lock.flush()?;
            0
        }
        Some(Command::Aggregate {
            statistics,
            no_sort,
            no_total,
            input,
        }) => aggregate::run(
            input,
            &walk_opts,
            aggregate::AggregateOptions {
                statistics: *statistics,
                no_sort: *no_sort,
                no_total: *no_total,
            },
        )?,
        Some(Command::Interactive {
            no_entry_check,
            input,
        }) => {
            if !io::stdout().is_terminal() {
                return Err(Box::<dyn Error>::from(
                    "Interactive mode requires a connected terminal",
                ));
            }
            interactive::run(input, &walk_opts, *no_entry_check)?
        }
        None => aggregate::run(
            &args.input,
            &walk_opts,
            aggregate::AggregateOptions::default(),
        )?,
    };
    Ok(code)
}

fn main() -> ExitCode {
    match run() {
        Ok(code) => ExitCode::from(code as u8),
        Err(err) => {
            eprintln!("Error: {}", err);
            ExitCode::from(1)
        }
    }
}
