    saved_stack: Vec<ViewState>,
}

struct MarkedItem {
    node: usize,
    deletion_errors: u64,
}

enum TraversalMessage {
    Entry(WalkEntry),
    Error,
    RootDone,
    Done,
}

pub struct App {
    graph: Graph,
    walk_opts: WalkOptions,
    no_entry_check: bool,

    current: usize,
    selected: Option<usize>,
    view_stack: Vec<ViewState>,
    checked_dirs: HashMap<usize, bool>,

    sort_mode: SortMode,
    show_mtime: bool,
    show_count: bool,
    graph_mode: GraphMode,

    marked: Vec<MarkedItem>,
    marked_selected: Option<usize>,

    active_pane: PaneKind,
    marked_visual_focus: bool,
    help_open: bool,
    help_scroll: u16,
