    message: Option<String>,
    exit_prompt: bool,
    should_quit: bool,

    // Traversal progress
    scanning: bool,
    processed: u64,
    traversal_started: Instant,
    traversal_elapsed: Duration,
    receiver: Option<Receiver<TraversalMessage>>,
    traversal_stack: Vec<usize>,
    traversal_root_count: usize,

    main_list_state: ListState,
    marked_list_state: ListState,
}

impl App {
    fn new(root_display: PathBuf, walk_opts: WalkOptions, no_entry_check: bool) -> Self {
        Self {
            graph: Graph::new(root_display.as_os_str().to_os_string()),
            walk_opts,
            no_entry_check,
            current: ROOT,
            selected: None,
            view_stack: Vec::new(),
            checked_dirs: HashMap::new(),
            sort_mode: SortMode::SizeDescending,
            show_mtime: false,
            show_count: false,
            graph_mode: GraphMode::PercentageAndBar,
            marked: Vec::new(),
            marked_selected: None,
            active_pane: PaneKind::Main,
            marked_visual_focus: false,
            help_open: false,
            help_scroll: 0,
            search: None,
            search_open: false,
            message: None,
            exit_prompt: false,
            should_quit: false,
            scanning: true,
            processed: 0,
            traversal_started: Instant::now(),
            traversal_elapsed: Duration::ZERO,
            receiver: None,
            traversal_stack: Vec::new(),
            traversal_root_count: 0,
            main_list_state: ListState::default(),
            marked_list_state: ListState::default(),
        }
    }

    fn actual_path(&self, id: usize) -> PathBuf {
        self.graph.graph_path(id, true)
    }

    fn open_path(&self, id: usize) -> PathBuf {
        self.graph.graph_path(id, false)
    }

    fn refresh_checked_dirs(&mut self) {
        self.checked_dirs.clear();
        if self.no_entry_check {
            return;
        }
        let children = self.graph.children(self.current);
        for child in children {
            let path = self.actual_path(child);
            let is_dir = fs::symlink_metadata(&path)
                .map(|md| md.is_dir())
                .unwrap_or(false);
            self.checked_dirs.insert(child, is_dir);
        }
    }

    fn checked_is_dir(&self, id: usize) -> bool {
        if self.is_search_view() {
            return false;
        }
        self.checked_dirs.get(&id).copied().unwrap_or(false)
    }

    fn is_search_view(&self) -> bool {
        self.search
            .as_ref()
            .map(|s| s.results.is_some())
            .unwrap_or(false)
            && self.current == ROOT
            && self.view_stack.is_empty()
    }

    fn current_entries(&self) -> Vec<usize> {
        let mut entries: Vec<usize> = if self.is_search_view() {
            self.search
                .as_ref()
                .and_then(|s| s.results.clone())
                .unwrap_or_default()
                .into_iter()
                .filter(|&id| self.graph.is_alive(id))
                .collect()
        } else {
            // The graph stores children in insertion order; the reference
            // UI enumerates them in reverse insertion order before sorting.
            let mut children = self.graph.children(self.current);
            children.reverse();
            children
        };
        self.sort_entries(&mut entries);
        entries
    }

    fn display_name_for_sort(&self, id: usize) -> PathBuf {
        let raw: OsString = if self.is_search_view() {
            self.open_path(id).as_os_str().to_os_string()
        } else {
            self.graph.nodes[id].name.clone()
        };
        let path = PathBuf::from(&raw);
        if self.checked_is_dir(id) {
            if let Some(std::path::Component::Normal(_)) = path.components().next() {
                let mut with_slash = OsString::from("/");
                with_slash.push(&raw);
                return PathBuf::from(with_slash);
            }
        }
        path
    }

    fn sort_entries(&self, entries: &mut Vec<usize>) {
        let graph = &self.graph;
        match self.sort_mode {
            SortMode::SizeAscending => entries.sort_by_key(|&id| graph.nodes[id].size),
            SortMode::SizeDescending => {
                entries.sort_by_key(|&id| std::cmp::Reverse(graph.nodes[id].size))
            }
            SortMode::ModifiedAscending => {
                entries.sort_by_key(|&id| graph.nodes[id].mtime)
            }
            SortMode::ModifiedDescending => {
                entries.sort_by_key(|&id| std::cmp::Reverse(graph.nodes[id].mtime))
            }
            SortMode::ItemsAscending => entries.sort_by_key(|&id| graph.nodes[id].count),
            SortMode::ItemsDescending => {
                entries.sort_by_key(|&id| std::cmp::Reverse(graph.nodes[id].count))
            }
            SortMode::NameAscending => {
                let keys: HashMap<usize, PathBuf> = entries
                    .iter()
                    .map(|&id| (id, self.display_name_for_sort(id)))
                    .collect();
                entries.sort_by(|a, b| keys[a].cmp(&keys[b]));
            }
            SortMode::NameDescending => {
                let keys: HashMap<usize, PathBuf> = entries
                    .iter()
                    .map(|&id| (id, self.display_name_for_sort(id)))
                    .collect();
                entries.sort_by(|a, b| keys[b].cmp(&keys[a]));
            }
        }
    }

    fn label_for(&self, id: usize) -> (String, bool) {
        let raw: OsString = if self.is_search_view() {
            self.open_path(id).as_os_str().to_os_string()
        } else {
            self.graph.nodes[id].name.clone()
        };
        let is_dir = self.checked_is_dir(id);
        let text = raw.to_string_lossy().into_owned();
        let label = if is_dir {
            let path = Path::new(&raw);
            if matches!(
                path.components().next(),
                Some(std::path::Component::Normal(_))
            ) {
                format!("/{}", text)
            } else {
                text
            }
        } else {
            format!(" {}", text)
        };
        (label, is_dir)
    }

    fn is_effectively_marked(&self, id: usize) -> bool {
        let mut current = Some(id);
        while let Some(node_id) = current {
            if self.marked.iter().any(|item| item.node == node_id) {
                return true;
            }
            current = self.graph.nodes[node_id].parent;
        }
        false
    }

    fn marked_totals(&self) -> (u64, u64) {
        let mut count = 0u64;
        let mut size = 0u64;
        for id in 1..self.graph.nodes.len() {
            if self.graph.is_alive(id) && self.is_effectively_marked(id) {
                count += 1;
                size += self.graph.nodes[id].own_size;
            }
        }
        (count, size)
    }

    fn current_title(&self) -> String {
        if self.is_search_view() || self.current == ROOT {
            self.graph.nodes[ROOT].name.to_string_lossy().into_owned()
        } else {
            self.open_path(self.current)
                .to_string_lossy()
                .into_owned()
        }
    }

    fn title_stats(&self) -> (usize, u64, u64) {
        if self.is_search_view() {
            let entries = self.current_entries();
            let total: u64 = entries.iter().map(|&id| self.graph.nodes[id].count).sum();
            let size: u64 = entries.iter().map(|&id| self.graph.nodes[id].size).sum();
            (entries.len(), total, size)
        } else if self.current == ROOT {
            let children = self.graph.children(ROOT);
            let total = self.graph.nodes[ROOT].count.saturating_sub(1);
            (children.len(), total, self.graph.nodes[ROOT].size)
        } else {
            let children = self.graph.children(self.current);
            let node = &self.graph.nodes[self.current];
            (
                children.len(),
                node.count.saturating_sub(1),
                node.size.saturating_sub(node.own_size),
            )
        }
    }

    fn ensure_selection(&mut self) {
        if self.scanning {
            return;
        }
        let entries = self.current_entries();
        if let Some(selected) = self.selected {
            if entries.contains(&selected) {
                return;
            }
        }
        self.selected = entries.first().copied();
    }

    fn select_by_index(&mut self, index: Option<usize>) {
        let entries = self.current_entries();
        self.selected = index.and_then(|i| entries.get(i).copied());
    }

    fn selected_index(&self, entries: &[usize]) -> Option<usize> {
        self.selected
            .and_then(|selected| entries.iter().position(|&id| id == selected))
    }

    fn move_selection(&mut self, delta: isize) {
        let entries = self.current_entries();
        if entries.is_empty() {
            self.selected = None;
            return;
        }
        let current = self.selected_index(&entries).unwrap_or(0);
        let new_index = (current as isize + delta).clamp(0, entries.len() as isize - 1);
        self.selected = Some(entries[new_index as usize]);
    }

    fn set_current(&mut self, node: usize, selected: Option<usize>) {
        self.current = node;
        self.refresh_checked_dirs();
        let entries = self.current_entries();
        self.selected = selected
            .filter(|id| entries.contains(id))
            .or_else(|| entries.first().copied());
        // Reset the scroll offset so the list widget scrolls the selection
        // into view from the top, matching navigation into a directory.
        self.main_list_state = ListState::default();
    }

    fn descend(&mut self) {
        let Some(selected) = self.selected else { return };
        if self.graph.children(selected).is_empty() {
            self.message = Some("Entry is a file or an empty directory".to_string());
            return;
        }
        let view = ViewState {
            current: self.current,
            search_results: if self.is_search_view() {
                self.search.as_ref().and_then(|s| s.results.clone())
            } else {
                None
            },
            selected: self.selected,
        };
        self.view_stack.push(view);
        self.set_current(selected, None);
    }

    fn ascend(&mut self) {
        if let Some(view) = self.view_stack.pop() {
            // If we are returning to a search-results view, the stored
            // results remain in the search state; merely restoring the
            // current node (the artificial root) is enough since
            // `is_search_view` takes the (now empty) stack into account.
            self.set_current(view.current, view.selected);
        } else {
            self.message = Some("Top level reached".to_string());
        }
    }
}
RS
"}

