    Bar,
    LargeBar,
}

impl GraphMode {
    fn next(self) -> Self {
        match self {
            Self::PercentageAndBar => Self::Percentage,
            Self::Percentage => Self::Bar,
            Self::Bar => Self::LargeBar,
            Self::LargeBar => Self::PercentageAndBar,
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PaneKind {
    Main,
    Help,
    Marked,
    Search,
}

#[derive(Clone)]
struct Node {
    name: OsString,
    parent: Option<usize>,
    children: Vec<usize>,
    own_size: u64,
    size: u64,
    count: u64,
    mtime: Option<SystemTime>,
    is_dir: bool,
    alive: bool,
}

impl Node {
    fn new(name: OsString, parent: Option<usize>, own_size: u64) -> Self {
        Self {
            name,
            parent,
            children: Vec::new(),
            own_size,
            size: own_size,
            count: 1,
            mtime: None,
            is_dir: false,
            alive: true,
        }
    }
}

struct Graph {
    nodes: Vec<Node>,
}

impl Graph {
    fn new(root_name: OsString) -> Self {
        let mut root = Node::new(root_name, None, 0);
        root.is_dir = true;
        Self { nodes: vec![root] }
    }

    fn add_node(&mut self, parent: usize, entry: &WalkEntry) -> usize {
        let id = self.nodes.len();
        let mut node = Node::new(entry.name.clone(), Some(parent), entry.size);
        node.mtime = entry.mtime;
        node.is_dir = entry.is_dir;
        self.nodes.push(node);
        self.nodes[parent].children.push(id);
        // Incrementally maintain aggregate sizes/counts along the ancestor
        // chain so partially-built graphs can be rendered while scanning.
        let mut current = Some(parent);
        while let Some(ancestor) = current {
            self.nodes[ancestor].size += entry.size;
            self.nodes[ancestor].count += 1;
            current = self.nodes[ancestor].parent;
        }
        id
    }

    fn is_alive(&self, id: usize) -> bool {
        self.nodes.get(id).map(|n| n.alive).unwrap_or(false)
    }

    fn children(&self, id: usize) -> Vec<usize> {
        self.nodes[id]
            .children
            .iter()
            .copied()
            .filter(|&child| self.is_alive(child))
            .collect()
    }

    fn subtree_ids(&self, root: usize) -> Vec<usize> {
        let mut out = Vec::new();
        let mut stack = vec![root];
        while let Some(id) = stack.pop() {
            if !self.is_alive(id) {
                continue;
            }
            out.push(id);
            // Push in reverse so traversal follows insertion order.
            for child in self.nodes[id].children.iter().rev() {
                if self.is_alive(*child) {
                    stack.push(*child);
                }
            }
        }
        out
    }

    fn remove_subtree(&mut self, root: usize) {
        if root == ROOT {
            return;
        }
        let ids = self.subtree_ids(root);
        if let Some(parent) = self.nodes[root].parent {
            self.nodes[parent].children.retain(|&c| c != root);
        }
        for id in ids {
            self.nodes[id].alive = false;
            self.nodes[id].children.clear();
        }
        self.recompute();
    }

    fn recompute(&mut self) {
        for node in self.nodes.iter_mut() {
            if node.alive {
                node.size = node.own_size;
                node.count = 1;
            }
        }
        for id in (1..self.nodes.len()).rev() {
            if !self.nodes[id].alive {
                continue;
            }
            if let Some(parent) = self.nodes[id].parent {
                let (size, count) = (self.nodes[id].size, self.nodes[id].count);
                if self.nodes[parent].alive {
                    self.nodes[parent].size += size;
                    self.nodes[parent].count += count;
                }
            }
        }
    }

    fn graph_path(&self, id: usize, include_root: bool) -> PathBuf {
        let mut names: Vec<OsString> = Vec::new();
        let mut current = Some(id);
        while let Some(node_id) = current {
            if node_id == ROOT {
                if include_root {
                    names.push(self.nodes[ROOT].name.clone());
                }
                break;
            }
            names.push(self.nodes[node_id].name.clone());
            current = self.nodes[node_id].parent;
        }
        names.reverse();
        let mut path = PathBuf::new();
        for name in names {
            path.push(name);
        }
        path
    }

    fn ancestors(&self, mut id: usize) -> Vec<usize> {
        let mut out = Vec::new();
        while let Some(parent) = self.nodes[id].parent {
            out.push(parent);
            id = parent;
        }
        out
    }
