#[derive(Clone)]
struct Node {
    name: OsString,
    parent: Option<usize>,
    children: Vec<usize>,
    own_size: u64,
    size: u64,
    count: u64,
    mtime: Option<SystemTime>,
    is_dir: bool,
    alive: bool,
}

impl Node {
    fn new(name: OsString, parent: Option<usize>, own_size: u64) -> Self {
        Self {
            name,
            parent,
            children: Vec::new(),
            own_size,
            size: own_size,
            count: 1,
            mtime: None,
            is_dir: false,
            alive: true,
        }
    }
}

struct Graph {
    nodes: Vec<Node>,
}

impl Graph {
    fn new(root_name: OsString) -> Self {
        let mut root = Node::new(root_name, None, 0);
        root.is_dir = true;
        Self { nodes: vec![root] }
    }

    fn add_node(&mut self, parent: usize, entry: &WalkEntry) -> usize {
        let id = self.nodes.len();
        let mut node = Node::new(entry.name.clone(), Some(parent), entry.size);
        node.mtime = entry.mtime;
        node.is_dir = entry.is_dir;
