        // chain so partially-built graphs can be rendered while scanning.
        let mut current = Some(parent);
        while let Some(ancestor) = current {
            self.nodes[ancestor].size += entry.size;
            self.nodes[ancestor].count += 1;
            current = self.nodes[ancestor].parent;
        }
        id
    }

    fn is_alive(&self, id: usize) -> bool {
        self.nodes.get(id).map(|n| n.alive).unwrap_or(false)
    }

    fn children(&self, id: usize) -> Vec<usize> {
        self.nodes[id]
            .children
            .iter()
            .copied()
            .filter(|&child| self.is_alive(child))
            .collect()
    }

    fn subtree_ids(&self, root: usize) -> Vec<usize> {
        let mut out = Vec::new();
        let mut stack = vec![root];
        while let Some(id) = stack.pop() {
            if !self.is_alive(id) {
                continue;
            }
            out.push(id);
            // Push in reverse so traversal follows insertion order.
            for child in self.nodes[id].children.iter().rev() {
                if self.is_alive(*child) {
                    stack.push(*child);
                }
            }
        }
        out
    }

