        if root == ROOT {
            return;
        }
        let ids = self.subtree_ids(root);
        if let Some(parent) = self.nodes[root].parent {
            self.nodes[parent].children.retain(|&c| c != root);
        }
        for id in ids {
            self.nodes[id].alive = false;
            self.nodes[id].children.clear();
        }
        self.recompute();
    }

    fn recompute(&mut self) {
        for node in self.nodes.iter_mut() {
            if node.alive {
                node.size = node.own_size;
                node.count = 1;
            }
        }
        for id in (1..self.nodes.len()).rev() {
            if !self.nodes[id].alive {
                continue;
            }
            if let Some(parent) = self.nodes[id].parent {
                let (size, count) = (self.nodes[id].size, self.nodes[id].count);
                if self.nodes[parent].alive {
                    self.nodes[parent].size += size;
                    self.nodes[parent].count += count;
                }
            }
        }
    }

