        let mut path = PathBuf::new();
        for name in names {
            path.push(name);
        }
        path
    }

    fn ancestors(&self, mut id: usize) -> Vec<usize> {
        let mut out = Vec::new();
        while let Some(parent) = self.nodes[id].parent {
            out.push(parent);
            id = parent;
        }
