fn format_bar(ratio: f64, width: usize) -> String {
    if width == 0 {
        return String::new();
    }
    let ratio = if ratio.is_finite() {
        ratio.clamp(0.0, 1.0)
    } else {
        0.0
    };
    let units = (ratio * width as f64 * 8.0).round() as usize;
    let full = (units / 8).min(width);
    let rem = units % 8;
    let mut bar = String::new();
    for _ in 0..full {
        bar.push('█');
    }
    if full < width && rem > 0 {
        bar.push(match rem {
            1 => '▏',
            2 => '▎',
            3 => '▍',
            4 => '▌',
            5 => '▋',
            6 => '▊',
            _ => '▉',
        });
    }
    while bar.chars().count() < width {
        bar.push(' ');
    }
    bar
}

fn graph_segment(mode: GraphMode, ratio: f64) -> String {
    match mode {
        GraphMode::PercentageAndBar => {
            format!(" {:6.1}%  {} ", ratio * 100.0, format_bar(ratio, 10))
        }
        GraphMode::Percentage => format!(" {:6.1}%  ", ratio * 100.0),
        GraphMode::Bar => format!(" {} ", format_bar(ratio, 10)),
        GraphMode::LargeBar => format!(" {} ", format_bar(ratio, 19)),
    }
}

