fn help_line_count() -> usize {
    // One leading blank line, then for each section: heading, blank,
    // entries (with an extra line for two-line descriptions), two blanks.
    let mut count = 1usize;
    for (_, entries) in HELP_SECTIONS {
        count += 2;
        for (_, _, extra) in *entries {
            count += if extra.is_empty() { 1 } else { 2 };
        }
        count += 2;
    }
    count
}

fn help_text() -> ratatui::text::Text<'static> {
    let mut lines: Vec<Line<'static>> = Vec::new();
    lines.push(Line::from(""));
    for (section, entries) in HELP_SECTIONS {
        lines.push(Line::from(vec![
            Span::raw(" "),
            Span::styled(
                *section,
                Style::default()
                    .add_modifier(Modifier::BOLD)
                    .add_modifier(Modifier::UNDERLINED),
            ),
        ]));
        lines.push(Line::from(""));
        for (key, description, extra) in *entries {
            lines.push(Line::from(vec![
                Span::raw(" "),
                Span::styled(
                    format!("{:>11}", key),
                    Style::default().fg(Color::Green),
                ),
                Span::raw(format!(" => {}", description)),
            ]));
            if !extra.is_empty() {
                lines.push(Line::from(format!("                {}", extra)));
            }
        }
        lines.push(Line::from(""));
        lines.push(Line::from(""));
    }
    ratatui::text::Text::from(lines)
}

