impl App {
    fn spawn_traversal(&mut self, roots: Vec<RootSpec>) {
        let (tx, rx) = mpsc::channel::<TraversalMessage>();
        let opts = self.walk_opts.clone();
        self.traversal_root_count = roots.len();
        std::thread::spawn(move || {
            let mut seen: HashSet<(u64, u64)> = HashSet::new();
            for root in &roots {
                log::info(&format!("Walking {:?}", root.display));
                let mut send_failed = false;
                walk_root(root, &opts, &mut seen, &mut |event| {
                    if send_failed {
                        return;
                    }
                    let message = match event {
                        WalkEvent::Entry(entry) => TraversalMessage::Entry(entry),
                        WalkEvent::Error => TraversalMessage::Error,
                    };
                    if tx.send(message).is_err() {
                        send_failed = true;
                    }
                });
                if send_failed || tx.send(TraversalMessage::RootDone).is_err() {
                    return;
                }
            }
            let _ = tx.send(TraversalMessage::Done);
        });
        self.receiver = Some(rx);
    }

    fn process_traversal_messages(&mut self) {
        let Some(receiver) = self.receiver.take() else {
            return;
        };
        let mut disconnected = false;
        loop {
            match receiver.try_recv() {
                Ok(TraversalMessage::Entry(entry)) => {
                    self.processed += 1;
                    if entry.io_error {
                        continue;
                    }
                    if entry.depth == 0 {
                        self.traversal_stack.clear();
                        let id = self.graph.add_node(ROOT, &entry);
                        self.traversal_stack.push(id);
                    } else {
                        while self.traversal_stack.len() > entry.depth {
                            self.traversal_stack.pop();
                        }
                        let Some(&parent) = self.traversal_stack.get(entry.depth - 1) else {
                            continue;
                        };
                        let id = self.graph.add_node(parent, &entry);
                        if self.traversal_stack.len() == entry.depth {
                            self.traversal_stack.push(id);
                        } else if self.traversal_stack.len() > entry.depth {
                            self.traversal_stack[entry.depth] = id;
                            self.traversal_stack.truncate(entry.depth + 1);
                        } else {
                            self.traversal_stack.push(id);
                        }
                    }
                }
                Ok(TraversalMessage::Error) => {}
                Ok(TraversalMessage::RootDone) => {
                    self.traversal_stack.clear();
                }
                Ok(TraversalMessage::Done) => {
                    self.scanning = false;
                    self.traversal_elapsed = self.traversal_started.elapsed();
                    self.refresh_checked_dirs();
                    self.selected = None;
                    self.ensure_selection();
                    disconnected = true;
                    break;
                }
                Err(TryRecvError::Empty) => break,
                Err(TryRecvError::Disconnected) => {
                    disconnected = true;
                    if self.scanning {
                        self.scanning = false;
                        self.traversal_elapsed = self.traversal_started.elapsed();
                        self.refresh_checked_dirs();
                        self.ensure_selection();
                    }
                    break;
                }
            }
        }
        if !disconnected {
            self.receiver = Some(receiver);
        }
    }

    fn set_active(&mut self, pane: PaneKind) {
        self.active_pane = pane;
        if pane != PaneKind::Marked {
            // Tab-style activation clears the sticky marked focus visuals;
            // callers that should preserve them set the flag again below.
        }
        self.marked_visual_focus = pane == PaneKind::Marked;
    }

    fn visible_panes(&self) -> Vec<PaneKind> {
        let mut panes = vec![PaneKind::Main];
        if self.help_open {
            panes.push(PaneKind::Help);
        }
        if !self.marked.is_empty() {
            panes.push(PaneKind::Marked);
        }
        if self.search_open {
            panes.push(PaneKind::Search);
        }
        panes
    }

    fn cycle_pane(&mut self) {
        let panes = self.visible_panes();
        if panes.len() <= 1 {
            return;
        }
        let index = panes.iter().position(|&p| p == self.active_pane).unwrap_or(0);
        let next = panes[(index + 1) % panes.len()];
        self.set_active(next);
    }

    fn is_pane_visually_focused(&self, pane: PaneKind) -> bool {
        match pane {
            PaneKind::Marked => self.marked_visual_focus,
            other => self.active_pane == other,
        }
    }

    fn toggle_help(&mut self) {
        if self.help_open && self.active_pane == PaneKind::Help {
            self.help_open = false;
            self.active_pane = PaneKind::Main;
        } else {
            self.help_open = true;
            // Preserve sticky marked visuals when opening help from the
            // marked pane, as the reference does.
            let sticky = self.marked_visual_focus;
            self.active_pane = PaneKind::Help;
            self.marked_visual_focus = sticky && !self.marked.is_empty();
        }
    }

    fn cancel_search(&mut self) {
        if let Some(search) = self.search.take() {
            if search.results.is_some() {
                self.view_stack = search.saved_stack;
                self.set_current(search.saved_view.current, search.saved_view.selected);
            }
        }
        self.search_open = false;
        self.active_pane = PaneKind::Main;
    }

    fn open_search(&mut self) {
        if self.search.is_none() {
            self.search = Some(SearchState {
                input: String::new(),
                case_sensitive: false,
                results: None,
                origin: self.current,
                saved_view: ViewState {
                    current: self.current,
                    search_results: None,
                    selected: self.selected,
                },
                saved_stack: self.view_stack.clone(),
            });
        }
        self.search_open = true;
        let sticky = self.marked_visual_focus;
        self.active_pane = PaneKind::Search;
        self.marked_visual_focus = sticky && !self.marked.is_empty();
    }

    fn close_current_pane(&mut self) {
        if self.exit_prompt {
            self.should_quit = true;
            return;
        }
        match self.active_pane {
            PaneKind::Help => {
                self.help_open = false;
                self.active_pane = PaneKind::Main;
            }
            PaneKind::Marked => {
                self.active_pane = PaneKind::Main;
                // marked_visual_focus intentionally stays set.
            }
            PaneKind::Search => {
                self.cancel_search();
            }
            PaneKind::Main => {
                if self.search_open {
                    self.cancel_search();
                } else if !self.marked.is_empty() {
                    self.exit_prompt = true;
                } else {
                    self.should_quit = true;
                }
            }
        }
    }
}
RS
"}

