impl App {
    fn spawn_traversal(&mut self, roots: Vec<RootSpec>) {
        let (tx, rx) = mpsc::channel::<TraversalMessage>();
        let opts = self.walk_opts.clone();
        self.traversal_root_count = roots.len();
        std::thread::spawn(move || {
            let mut seen: HashSet<(u64, u64)> = HashSet::new();
            for root in &roots {
                log::info(&format!("Walking {:?}", root.display));
                let mut send_failed = false;
                walk_root(root, &opts, &mut seen, &mut |event| {
                    if send_failed {
                        return;
                    }
                    let message = match event {
                        WalkEvent::Entry(entry) => TraversalMessage::Entry(entry),
                        WalkEvent::Error => TraversalMessage::Error,
                    };
                    if tx.send(message).is_err() {
                        send_failed = true;
                    }
                });
                if send_failed || tx.send(TraversalMessage::RootDone).is_err() {
                    return;
                }
            }
            let _ = tx.send(TraversalMessage::Done);
        });
        self.receiver = Some(rx);
    }

    fn process_traversal_messages(&mut self) {
        let Some(receiver) = self.receiver.take() else {
            return;
        };
        let mut disconnected = false;
        loop {
            match receiver.try_recv() {
                Ok(TraversalMessage::Entry(entry)) => {
                    self.processed += 1;
                    if entry.io_error {
                        continue;
                    }
                    if entry.depth == 0 {
                        self.traversal_stack.clear();
                        let id = self.graph.add_node(ROOT, &entry);
                        self.traversal_stack.push(id);
                    } else {
                        while self.traversal_stack.len() > entry.depth {
                            self.traversal_stack.pop();
                        }
                        let Some(&parent) = self.traversal_stack.get(entry.depth - 1) else {
                            continue;
                        };
                        let id = self.graph.add_node(parent, &entry);
                        if self.traversal_stack.len() == entry.depth {
                            self.traversal_stack.push(id);
                        } else if self.traversal_stack.len() > entry.depth {
                            self.traversal_stack[entry.depth] = id;
                            self.traversal_stack.truncate(entry.depth + 1);
                        } else {
                            self.traversal_stack.push(id);
                        }
                    }
                }
                Ok(TraversalMessage::Error) => {}
                Ok(TraversalMessage::RootDone) => {
                    self.traversal_stack.clear();
                }
                Ok(TraversalMessage::Done) => {
                    self.scanning = false;
                    self.traversal_elapsed = self.traversal_started.elapsed();
                    self.refresh_checked_dirs();
                    self.selected = None;
                    self.ensure_selection();
                    disconnected = true;
