    }

    fn open_search(&mut self) {
        if self.search.is_none() {
            self.search = Some(SearchState {
                input: String::new(),
                case_sensitive: false,
                results: None,
                origin: self.current,
                saved_view: ViewState {
                    current: self.current,
                    search_results: None,
                    selected: self.selected,
                },
                saved_stack: self.view_stack.clone(),
            });
        }
        self.search_open = true;
        let sticky = self.marked_visual_focus;
        self.active_pane = PaneKind::Search;
        self.marked_visual_focus = sticky && !self.marked.is_empty();
    }

    fn close_current_pane(&mut self) {
        if self.exit_prompt {
            self.should_quit = true;
            return;
        }
        match self.active_pane {
            PaneKind::Help => {
                self.help_open = false;
                self.active_pane = PaneKind::Main;
            }
            PaneKind::Marked => {
                self.active_pane = PaneKind::Main;
                // marked_visual_focus intentionally stays set.
            }
