                self.cancel_search();
            }
            PaneKind::Main => {
                if self.search_open {
                    self.cancel_search();
                } else if !self.marked.is_empty() {
                    self.exit_prompt = true;
                } else {
                    self.should_quit = true;
                }
            }
        }
    }
}
