        .backslash_escape(true)
        .build()
        .ok()
        .map(|glob| glob.compile_matcher())
}

fn relative_under(app: &App, node: usize, scope: usize) -> PathBuf {
    let mut names: Vec<OsString> = Vec::new();
    let mut current = Some(node);
    while let Some(id) = current {
        if id == scope {
            break;
        }
        names.push(app.graph.nodes[id].name.clone());
        current = app.graph.nodes[id].parent;
        if id == ROOT {
            break;
        }
    }
    names.reverse();
    let mut path = PathBuf::new();
    for name in names {
        path.push(name);
    }
    path
