        let candidate = relative_under(app, node, scope);
        matcher.is_match(candidate)
    } else {
        let name = &app.graph.nodes[node].name;
        let file_name = Path::new(name)
            .file_name()
            .unwrap_or_else(|| OsStr::new(name));
        matcher.is_match(Path::new(file_name))
    }
