        if let Ok(read_dir) = fs::read_dir(path) {
            for entry in read_dir.flatten() {
                delete_path_best_effort(&entry.path());
            }
        }
        let _ = fs::remove_dir(path);
    } else {
        let _ = fs::remove_file(path);
    }
}

fn percent_encode_path(path: &Path) -> String {
    let bytes = path.as_os_str().as_encoded_bytes();
    let mut out = String::new();
    for &byte in bytes {
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' | b'/' => {
                out.push(byte as char)
            }
            _ => out.push_str(&format!("%{:02X}", byte)),
        }
    }
    out
}

fn trash_path(path: &Path) -> io::Result<()> {
    let absolute = if path.is_absolute() {
        path.to_path_buf()
    } else {
        std::env::current_dir()?.join(path)
    };
    let data_home = std::env::var_os("XDG_DATA_HOME")
        .filter(|value| !value.is_empty())
        .map(PathBuf::from)
        .or_else(|| {
            std::env::var_os("HOME")
                .filter(|value| !value.is_empty())
                .map(|home| PathBuf::from(home).join(".local").join("share"))
        })
        .ok_or_else(|| io::Error::new(io::ErrorKind::NotFound, "no home directory"))?;
    let trash_root = data_home.join("Trash");
    let files_dir = trash_root.join("files");
    let info_dir = trash_root.join("info");
    fs::create_dir_all(&files_dir)?;
    fs::create_dir_all(&info_dir)?;
    let base_name = path
        .file_name()
        .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "path has no file name"))?
        .to_os_string();
    let mut candidate = base_name.clone();
    let mut counter = 1u64;
    loop {
        let dest = files_dir.join(&candidate);
        let mut info_name = candidate.clone();
        info_name.push(".trashinfo");
        let info_path = info_dir.join(&info_name);
        if fs::symlink_metadata(&dest).is_err() && fs::symlink_metadata(&info_path).is_err() {
            let info_content = format!(
                "[Trash Info]\nPath={}\nDeletionDate={}\n",
                percent_encode_path(&absolute),
                Local::now().format("%Y-%m-%dT%H:%M:%S")
            );
            fs::write(&info_path, info_content)?;
            match fs::rename(path, &dest) {
                Ok(()) => return Ok(()),
                Err(err) => {
                    let _ = fs::remove_file(&info_path);
                    return Err(err);
                }
            }
        }
        candidate = {
            let mut name = base_name.clone();
            name.push(format!(" {}", counter));
            counter += 1;
            name
        };
    }
}
