impl App {
    fn toggle_marked(&mut self, node: usize) {
        if let Some(position) = self.marked.iter().position(|item| item.node == node) {
            self.marked.remove(position);
        } else {
            self.marked.push(MarkedItem {
                node,
                deletion_errors: 0,
            });
        }
        self.sync_marked_selection();
    }

    fn mark_only(&mut self, node: usize) {
        if !self.marked.iter().any(|item| item.node == node) {
