                self.active_pane = PaneKind::Main;
            }
            return;
        }
        if let Some(selected) = self.marked_selected {
            if self.marked.iter().any(|item| item.node == selected) {
                return;
            }
        }
        self.marked_selected = self.marked.first().map(|item| item.node);
    }

    fn execute_search(&mut self) {
        let Some(search) = self.search.as_ref() else { return };
        let input = search.input.clone();
        if input.trim().is_empty() {
            self.message = Some("Glob was empty or only whitespace".to_string());
            return;
        }
        let case_sensitive = search.case_sensitive;
        let in_results_view = self.is_search_view();
        let scope = if in_results_view {
            search.origin
        } else {
            self.current
        };
        let matcher = match build_glob_matcher(&input, case_sensitive) {
            Some(matcher) => matcher,
            None => {
                self.message = Some("No match found".to_string());
                return;
            }
        };
        let mut results: Vec<usize> = Vec::new();
        fn visit(
            app: &App,
            node: usize,
            scope: usize,
            matcher: &globset::GlobMatcher,
            pattern_has_slash: bool,
            results: &mut Vec<usize>,
        ) {
            for child in app.graph.children(node) {
                if matches_glob(app, child, scope, matcher, pattern_has_slash) {
                    results.push(child);
                } else if !app.graph.children(child).is_empty() {
                    visit(app, child, scope, matcher, pattern_has_slash, results);
                }
            }
        }
        let pattern_has_slash = input.contains('/');
        visit(self, scope, scope, &matcher, pattern_has_slash, &mut results);
        if results.is_empty() {
            self.message = Some("No match found".to_string());
            return;
        }
        if let Some(search) = self.search.as_mut() {
            if !in_results_view {
                search.origin = scope;
                search.saved_view = ViewState {
                    current: self.current,
                    search_results: None,
                    selected: self.selected,
                };
                search.saved_stack = self.view_stack.clone();
            }
            search.results = Some(results);
        }
        self.current = ROOT;
        self.view_stack.clear();
        self.checked_dirs.clear();
        self.main_list_state = ListState::default();
        let entries = self.current_entries();
        self.selected = entries.first().copied();
        self.active_pane = PaneKind::Main;
    }

    fn open_selected(&mut self) {
        let Some(selected) = self.selected else { return };
        let path = self.open_path(selected);
        let _ = std::process::Command::new("xdg-open")
            .arg(&path)
            .stdin(std::process::Stdio::null())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn();
    }

    fn refresh_roots(&mut self, roots: Vec<usize>) {
        if roots.is_empty() {
            return;
        }
        let started = Instant::now();
        let mut processed = 0u64;
        let mut seen: HashSet<(u64, u64)> = HashSet::new();
        // Existing entries that stay counted for hard-link de-duplication
        // are not tracked by the reference refresh either; it performs a
        // fresh traversal of the refreshed roots.
        for node_id in roots {
            if !self.graph.is_alive(node_id) {
                continue;
            }
            let root_spec = RootSpec {
                path: self.actual_path(node_id),
                display: PathBuf::from(&self.graph.nodes[node_id].name),
            };
            let mut fresh: Vec<WalkEntry> = Vec::new();
            let mut got_root = false;
            walk_root(&root_spec, &self.walk_opts, &mut seen, &mut |event| match event {
                WalkEvent::Entry(entry) => {
                    processed += 1;
                    if entry.depth == 0 {
                        got_root = true;
                    }
                    if !entry.io_error {
                        fresh.push(entry);
                    }
                }
                WalkEvent::Error => {}
            });
            if !got_root {
                self.graph.remove_subtree(node_id);
                continue;
            }
            // Remove old descendants.
            let old_descendants: Vec<usize> = self
                .graph
                .subtree_ids(node_id)
                .into_iter()
                .filter(|&id| id != node_id)
                .collect();
            for id in old_descendants {
                self.graph.nodes[id].alive = false;
                self.graph.nodes[id].children.clear();
            }
            self.graph.nodes[node_id].children.clear();
            // Apply the fresh entries.
            let mut stack: Vec<usize> = Vec::new();
            for entry in &fresh {
                if entry.depth == 0 {
                    let node = &mut self.graph.nodes[node_id];
                    node.own_size = entry.size;
                    node.size = entry.size;
                    node.count = 1;
                    node.mtime = entry.mtime;
                    node.is_dir = entry.is_dir;
                    stack.clear();
                    stack.push(node_id);
                } else {
                    while stack.len() > entry.depth {
                        stack.pop();
                    }
                    let Some(&parent) = stack.get(entry.depth - 1) else {
                        continue;
                    };
                    let id = self.graph.nodes.len();
                    let mut node = Node::new(entry.name.clone(), Some(parent), entry.size);
                    node.mtime = entry.mtime;
                    node.is_dir = entry.is_dir;
                    self.graph.nodes.push(node);
                    self.graph.nodes[parent].children.push(id);
                    if stack.len() == entry.depth {
                        stack.push(id);
                    } else if stack.len() > entry.depth {
                        stack[entry.depth] = id;
                        stack.truncate(entry.depth + 1);
                    } else {
                        stack.push(id);
                    }
                }
            }
            self.graph.recompute();
        }
        self.marked
            .retain(|item| self.graph.is_alive(item.node));
        self.sync_marked_selection();
        self.processed = processed;
        self.traversal_elapsed = started.elapsed();
        self.refresh_checked_dirs();
        self.ensure_selection();
    }

    fn delete_marked(&mut self, trash: bool) {
        if self.marked.is_empty() {
            return;
        }
        let items: Vec<usize> = self.marked.iter().map(|item| item.node).collect();
        for node_id in items {
            if !self.graph.is_alive(node_id) {
                continue;
            }
            let path = self.actual_path(node_id);
            if trash {
                let _ = trash_path(&path);
            } else {
                delete_path_best_effort(&path);
            }
            let remaining = self
                .graph
                .subtree_ids(node_id)
                .into_iter()
                .filter(|&id| fs::symlink_metadata(self.actual_path(id)).is_ok())
                .count() as u64;
            if remaining == 0 {
                self.graph.remove_subtree(node_id);
            } else if let Some(item) = self.marked.iter_mut().find(|item| item.node == node_id) {
                item.deletion_errors = remaining;
            }
        }
        self.marked
            .retain(|item| self.graph.is_alive(item.node));
        self.sync_marked_selection();
        self.graph.recompute();
        self.refresh_checked_dirs();
        if !self.marked.is_empty() {
            // Stay in the marked pane so the user can see deletion errors.
        } else {
            self.active_pane = PaneKind::Main;
        }
        self.ensure_selection();
    }
}

fn build_glob_matcher(pattern: &str, case_sensitive: bool) -> Option<globset::GlobMatcher> {
    let mut escaped = String::with_capacity(pattern.len());
    for ch in pattern.chars() {
        if ch == '{' || ch == '}' {
            escaped.push('\\');
        }
        escaped.push(ch);
    }
    globset::GlobBuilder::new(&escaped)
        .literal_separator(true)
        .case_insensitive(!case_sensitive)
        .backslash_escape(true)
        .build()
        .ok()
        .map(|glob| glob.compile_matcher())
}

fn relative_under(app: &App, node: usize, scope: usize) -> PathBuf {
    let mut names: Vec<OsString> = Vec::new();
    let mut current = Some(node);
    while let Some(id) = current {
        if id == scope {
            break;
        }
        names.push(app.graph.nodes[id].name.clone());
        current = app.graph.nodes[id].parent;
        if id == ROOT {
            break;
        }
    }
    names.reverse();
    let mut path = PathBuf::new();
    for name in names {
        path.push(name);
    }
    path
}

fn matches_glob(
    app: &App,
    node: usize,
    scope: usize,
    matcher: &globset::GlobMatcher,
    pattern_has_slash: bool,
) -> bool {
    if pattern_has_slash {
        let candidate = relative_under(app, node, scope);
        matcher.is_match(candidate)
    } else {
        let name = &app.graph.nodes[node].name;
        let file_name = Path::new(name)
            .file_name()
            .unwrap_or_else(|| OsStr::new(name));
        matcher.is_match(Path::new(file_name))
    }
}

fn delete_path_best_effort(path: &Path) {
    let Ok(md) = fs::symlink_metadata(path) else {
        return;
    };
    if md.is_dir() {
        if let Ok(read_dir) = fs::read_dir(path) {
            for entry in read_dir.flatten() {
                delete_path_best_effort(&entry.path());
            }
        }
        let _ = fs::remove_dir(path);
    } else {
        let _ = fs::remove_file(path);
    }
}

fn percent_encode_path(path: &Path) -> String {
    let bytes = path.as_os_str().as_encoded_bytes();
    let mut out = String::new();
    for &byte in bytes {
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' | b'/' => {
                out.push(byte as char)
            }
            _ => out.push_str(&format!("%{:02X}", byte)),
        }
    }
    out
}

