impl App {
    fn handle_key(&mut self, key: KeyEvent) {
        if key.kind == KeyEventKind::Release {
            return;
        }
        // Any key first clears a transient message; the exit prompt is
        // only confirmed by q/<Esc> and cancelled by other keys.
        let is_exit_confirm = matches!(key.code, KeyCode::Char('q') | KeyCode::Esc)
            && self.active_pane != PaneKind::Search;
        if self.exit_prompt && !is_exit_confirm {
            self.exit_prompt = false;
        }
        if !matches!(key.code, KeyCode::Char('c') if key.modifiers.contains(KeyModifiers::CONTROL)) {
            self.message = None;
        }

        if self.active_pane == PaneKind::Search {
            self.handle_search_key(key);
            return;
        }

        if key.modifiers.contains(KeyModifiers::CONTROL) && key.code == KeyCode::Char('c') {
            self.should_quit = true;
            return;
        }

        match key.code {
            KeyCode::Tab => {
                self.cycle_pane();
                return;
            }
            KeyCode::Char('?') => {
                self.toggle_help();
                return;
            }
            KeyCode::Char('/') => {
                self.open_search();
                return;
            }
            KeyCode::Esc => {
                self.close_current_pane();
                return;
            }
            KeyCode::Char('q') if !key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.close_current_pane();
                return;
            }
            _ => {}
        }

        match self.active_pane {
            PaneKind::Main => self.handle_main_key(key),
            PaneKind::Help => self.handle_help_key(key),
            PaneKind::Marked => self.handle_marked_key(key),
            PaneKind::Search => unreachable!(),
        }
    }

    fn navigation_delta(&mut self, key: KeyEvent) -> Option<isize> {
        match key.code {
            KeyCode::Char('j') | KeyCode::Down => Some(1),
            KeyCode::Char('k') | KeyCode::Up => Some(-1),
            KeyCode::PageDown => Some(10),
            KeyCode::PageUp => Some(-10),
            KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => Some(10),
            KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => Some(-10),
            _ => None,
        }
    }

    fn handle_main_key(&mut self, key: KeyEvent) {
        if let Some(delta) = self.navigation_delta(key) {
            // `d` without modifiers is mark-move, handled below.
            if !(key.code == KeyCode::Char('d')
                && !key.modifiers.contains(KeyModifiers::CONTROL))
            {
                self.move_selection(delta);
                return;
            }
        }
        match key.code {
            KeyCode::Char('H') | KeyCode::Home => self.select_by_index(Some(0)),
            KeyCode::Char('G') | KeyCode::End => {
                let entries = self.current_entries();
                self.selected = entries.last().copied();
            }
            KeyCode::Char('o') | KeyCode::Char('l') | KeyCode::Enter | KeyCode::Right => {
                self.descend()
            }
            KeyCode::Char('u')
                if !key.modifiers.contains(KeyModifiers::CONTROL) =>
            {
                self.ascend()
            }
            KeyCode::Char('h') | KeyCode::Left | KeyCode::Backspace => self.ascend(),
            KeyCode::Char('s') => {
                self.sort_mode = match self.sort_mode {
                    SortMode::SizeDescending => SortMode::SizeAscending,
                    _ => SortMode::SizeDescending,
                };
            }
            KeyCode::Char('m') => {
                self.sort_mode = match self.sort_mode {
                    SortMode::ModifiedDescending => SortMode::ModifiedAscending,
                    _ => SortMode::ModifiedDescending,
                };
            }
            KeyCode::Char('M') => {
                self.show_mtime = !self.show_mtime;
            }
            KeyCode::Char('c') => {
                self.sort_mode = match self.sort_mode {
                    SortMode::ItemsDescending => SortMode::ItemsAscending,
                    _ => SortMode::ItemsDescending,
                };
            }
            KeyCode::Char('C') => {
                self.show_count = !self.show_count;
            }
            KeyCode::Char('n') => {
                self.sort_mode = match self.sort_mode {
                    SortMode::NameAscending => SortMode::NameDescending,
                    _ => SortMode::NameAscending,
                };
            }
            KeyCode::Char('g') | KeyCode::Char('S') => {
                self.graph_mode = self.graph_mode.next();
            }
            KeyCode::Char('O') => self.open_selected(),
            KeyCode::Char(' ') => {
                if let Some(selected) = self.selected {
                    self.toggle_marked(selected);
                }
            }
            KeyCode::Char('d') => {
                if let Some(selected) = self.selected {
                    self.toggle_marked(selected);
                    self.move_selection(1);
                }
            }
            KeyCode::Char('x') => {
                if let Some(selected) = self.selected {
                    self.mark_only(selected);
                    self.move_selection(1);
                }
            }
            KeyCode::Char('a') => {
                for node in self.current_entries() {
                    self.toggle_marked(node);
                }
            }
            KeyCode::Char('r') => {
                if let Some(selected) = self.selected {
                    self.refresh_roots(vec![selected]);
                }
            }
            KeyCode::Char('R') => {
                let roots = self.current_entries();
                self.refresh_roots(roots);
            }
            _ => {}
        }
    }

    fn handle_help_key(&mut self, key: KeyEvent) {
        let max_scroll = self.help_max_scroll();
        match key.code {
            KeyCode::Char('j') | KeyCode::Down => {
                self.help_scroll = (self.help_scroll + 1).min(max_scroll);
            }
            KeyCode::Char('k') | KeyCode::Up => {
                self.help_scroll = self.help_scroll.saturating_sub(1);
            }
            KeyCode::PageDown => {
                self.help_scroll = (self.help_scroll + 10).min(max_scroll);
            }
            KeyCode::PageUp => {
                self.help_scroll = self.help_scroll.saturating_sub(10);
            }
            KeyCode::Char('d') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.help_scroll = (self.help_scroll + 10).min(max_scroll);
            }
            KeyCode::Char('u') if key.modifiers.contains(KeyModifiers::CONTROL) => {
                self.help_scroll = self.help_scroll.saturating_sub(10);
            }
            KeyCode::Char('H') | KeyCode::Home => {
                self.help_scroll = 0;
            }
            KeyCode::Char('G') | KeyCode::End => {
                self.help_scroll = max_scroll;
            }
            _ => {}
        }
    }

    fn help_max_scroll(&self) -> u16 {
        // The viewport height is recorded during rendering in
        // `help_viewport_height`; before the first render it is zero and
        // scrolling is effectively unbounded but clamped by content.
        let content = help_line_count() as u16;
        content.saturating_sub(self.help_viewport_height)
    }

    fn move_marked_selection(&mut self, delta: isize) {
        if self.marked.is_empty() {
            self.marked_selected = None;
            return;
        }
        let current = self
            .marked_selected
            .and_then(|selected| self.marked.iter().position(|item| item.node == selected))
            .unwrap_or(0);
        let new_index =
            (current as isize + delta).clamp(0, self.marked.len() as isize - 1) as usize;
        self.marked_selected = Some(self.marked[new_index].node);
    }

    fn handle_marked_key(&mut self, key: KeyEvent) {
        if key.modifiers.contains(KeyModifiers::CONTROL) && key.code == KeyCode::Char('r') {
            self.delete_marked(false);
            return;
        }
        if key.modifiers.contains(KeyModifiers::CONTROL) && key.code == KeyCode::Char('t') {
            self.delete_marked(true);
            return;
        }
        if let Some(delta) = self.navigation_delta(key) {
            if !(key.code == KeyCode::Char('d')
                && !key.modifiers.contains(KeyModifiers::CONTROL))
            {
                self.move_marked_selection(delta);
                return;
            }
        }
        match key.code {
            KeyCode::Char('H') | KeyCode::Home => {
                self.marked_selected = self.marked.first().map(|item| item.node);
            }
            KeyCode::Char('G') | KeyCode::End => {
                self.marked_selected = self.marked.last().map(|item| item.node);
            }
            KeyCode::Char(' ') | KeyCode::Char('d') | KeyCode::Char('x') => {
                if let Some(selected) = self.marked_selected {
                    let index = self
                        .marked
                        .iter()
                        .position(|item| item.node == selected)
                        .unwrap_or(0);
                    self.marked.remove(index);
                    if self.marked.is_empty() {
                        self.marked_selected = None;
                        self.marked_visual_focus = false;
                        self.active_pane = PaneKind::Main;
                    } else {
                        let new_index = index.min(self.marked.len() - 1);
                        self.marked_selected = Some(self.marked[new_index].node);
                    }
                }
            }
            KeyCode::Char('a') => {
