            Style::default().fg(Color::DarkGray)
        };
        let mut block = Block::default()
            .borders(Borders::ALL)
            .border_style(style)
            .title_top(Line::from(title).left_aligned());
        if focused {
            if let Some(text) = top_right {
                block = block.title_top(Line::from(text).right_aligned());
            }
            if let Some(text) = bottom_right {
                block = block.title_bottom(Line::from(text).right_aligned());
            }
        }
        block
    }

    fn draw(&mut self, frame: &mut Frame<'_>) {
        let area = frame.area();
        let vertical = Layout::default()
            .direction(Direction::Vertical)
            .constraints([
                Constraint::Length(1),
                Constraint::Min(0),
                Constraint::Length(1),
            ])
            .split(area);
        self.draw_header(frame, vertical[0]);
        self.draw_body(frame, vertical[1]);
        self.draw_footer(frame, vertical[2]);
    }

    fn draw_header(&self, frame: &mut Frame<'_>, area: Rect) {
        let background = if self.active_pane == PaneKind::Marked {
            Color::LightRed
        } else if !self.marked.is_empty() {
            Color::Yellow
        } else {
            Color::White
        };
        let paragraph = Paragraph::new(header_text())
            .style(Style::default().fg(Color::Black).bg(background));
        frame.render_widget(paragraph, area);
    }

    fn draw_body(&mut self, frame: &mut Frame<'_>, area: Rect) {
        let has_right = self.help_open || !self.marked.is_empty();
        let horizontal_constraints: &[Constraint] = if has_right {
            &[Constraint::Percentage(50), Constraint::Percentage(50)]
        } else {
            &[Constraint::Percentage(100)]
        };
        let horizontal = Layout::default()
            .direction(Direction::Horizontal)
            .constraints(horizontal_constraints)
            .split(area);
        let left_area = horizontal[0];
        // Left column: main pane with the search pane below it.
        if self.search_open {
            let left_vertical = Layout::default()
                .direction(Direction::Vertical)
                .constraints([Constraint::Min(0), Constraint::Length(3)])
                .split(left_area);
            self.draw_main(frame, left_vertical[0]);
            self.draw_search(frame, left_vertical[1]);
        } else {
            self.draw_main(frame, left_area);
        }
        if has_right {
            let right_area = horizontal[1];
            let both = self.help_open && !self.marked.is_empty();
            if both {
                let right_vertical = Layout::default()
                    .direction(Direction::Vertical)
                    .constraints([Constraint::Percentage(50), Constraint::Percentage(50)])
                    .split(right_area);
                self.draw_help(frame, right_vertical[0]);
                self.draw_marked(frame, right_vertical[1]);
            } else if self.help_open {
                self.draw_help(frame, right_area);
            } else {
                self.draw_marked(frame, right_area);
            }
        }
    }

    fn draw_main(&mut self, frame: &mut Frame<'_>, area: Rect) {
        let (visible, total, total_size) = self.title_stats();
        let title = format!(
            " {} ({} visible, {} total, {}) ",
            self.current_title(),
            visible,
            format_count(total),
            formatted_trimmed(self.walk_opts.format, total_size)
        );
        let block = self.pane_block(
            title,
            PaneKind::Main,
            Some(NAV_TITLE),
            Some(" mark-move = d | mark-toggle = space | toggle-all = a "),
        );
        let inner = block.inner(area);
        let entries = self.current_entries();
        let selected_index = if self.scanning {
            None
        } else {
            self.selected_index(&entries)
        };
        self.main_list_state.select(selected_index);
        let show_mtime = self.show_mtime
            || matches!(
                self.sort_mode,
                SortMode::ModifiedAscending | SortMode::ModifiedDescending
            );
        let show_count = self.show_count
            || matches!(
                self.sort_mode,
                SortMode::ItemsAscending | SortMode::ItemsDescending
            );
        let items: Vec<ListItem<'static>> = entries
            .iter()
            .map(|&id| {
                let node = &self.graph.nodes[id];
                let ratio = if total_size > 0 {
                    node.size as f64 / total_size as f64
                } else {
                    0.0
                };
                let mut spans: Vec<Span<'static>> = Vec::new();
                if show_mtime {
                    let date = node
                        .mtime
                        .map(|time| {
                            DateTime::<Local>::from(time)
                                .format("%d/%m/%Y %H:%M:%S")
                                .to_string()
                        })
                        .unwrap_or_default();
                    spans.push(Span::raw(format!(" {:19} |", date)));
                }
                spans.push(Span::styled(
                    self.walk_opts.format.format(node.size),
                    Style::default().fg(Color::Green),
                ));
                spans.push(Span::raw(format!(
                    " |{}|",
                    graph_segment(self.graph_mode, ratio)
                )));
                if show_count {
                    let count_text = if node.count > 1 {
                        format_count(node.count)
                    } else {
                        String::new()
                    };
                    spans.push(Span::raw(format!(" {:>4} |", count_text)));
                }
                let (label, is_dir) = self.label_for(id);
                let name_style = if self.is_effectively_marked(id) {
                    Style::default().fg(MARKED_COLOR)
