            let instruction_area = Rect {
                height: 1,
                ..inner
            };
            let instruction = Paragraph::new(Line::from(vec![
                Span::styled(
                    " Ctrl + t ",
                    Style::default().fg(Color::White).bg(Color::Black),
                ),
                Span::styled(
                    " to trash or ",
                    Style::default().fg(Color::Black).bg(Color::Yellow),
                ),
                Span::styled(
                    " Ctrl + r ",
                    Style::default()
                        .fg(Color::LightRed)
                        .bg(Color::Black)
                        .add_modifier(Modifier::SLOW_BLINK),
                ),
                Span::styled(
                    " to delete without prompt",
                    Style::default().fg(Color::Black).bg(Color::Yellow),
                ),
            ]));
            frame.render_widget(instruction, instruction_area);
            Rect {
                y: inner.y + 1,
                height: inner.height.saturating_sub(1),
                ..inner
            }
        } else {
            inner
        };
        let selected_index = self
            .marked_selected
            .and_then(|selected| {
                self.marked
                    .iter()
                    .position(|item| item.node == selected)
            });
        self.marked_list_state.select(selected_index);
        let items: Vec<ListItem<'static>> = self
            .marked
            .iter()
            .map(|item| {
                let node = &self.graph.nodes[item.node];
                let mut name = self
                    .open_path(item.node)
                    .to_string_lossy()
                    .into_owned();
                if item.deletion_errors > 0 {
                    name.push_str(&format!(
                        "  {} IO deletion errors",
                        item.deletion_errors
                    ));
                }
                let name_text = format!(" {}", name);
                let size_text = self.walk_opts.format.format(node.size);
                let available = (list_area.width as usize).saturating_sub(1);
                let name_width = unicode_width_of(&name_text);
                let size_width = unicode_width_of(&size_text);
                let padding = available.saturating_sub(name_width + size_width);
                ListItem::new(Line::from(vec![
                    Span::styled(name_text, Style::default().fg(MARKED_COLOR)),
                    Span::raw(" ".repeat(padding)),
                    Span::styled(size_text, Style::default().fg(Color::Green)),
                    Span::raw(" "),
                ]))
            })
            .collect();
        let list = List::new(items)
            .highlight_style(Style::default().add_modifier(Modifier::REVERSED));
        frame.render_stateful_widget(list, list_area, &mut self.marked_list_state);
        self.draw_scrollbar(
            frame,
            area,
            self.marked.len(),
            selected_index,
            list_area.height,
        );
