    fn draw_search(&mut self, frame: &mut Frame<'_>, area: Rect) {
        let (input, cursor, case_sensitive) = self
            .search
            .as_ref()
            .map(|search| {
                (
                    search.input.clone(),
                    search.cursor,
                    search.case_sensitive,
                )
            })
            .unwrap_or_default();
        let title = if case_sensitive {
            "Git-Glob (case-sensitive)".to_string()
        } else {
            "Git-Glob (case-insensitive)".to_string()
        };
        let block = self.pane_block(
            title,
            PaneKind::Search,
            Some(" search = enter | case = ^f | cancel = esc "),
            None,
        );
        let paragraph = Paragraph::new(Line::from(format!(" {}", input))).block(block);
        frame.render_widget(paragraph, area);
        if self.active_pane == PaneKind::Search && area.width > 2 && area.height > 1 {
            let before: String = input.chars().take(cursor).collect();
            let cursor_x = area.x + 2 + unicode_width_of(&before) as u16;
            let cursor_y = area.y + 1;
            if cursor_x < area.x + area.width - 1 {
                frame.set_cursor_position((cursor_x, cursor_y));
            }
        }
    }

    fn draw_footer(&self, frame: &mut Frame<'_>, area: Rect) {
        if self.exit_prompt {
            let paragraph = Paragraph::new("Press esc or q again to exit...").style(
                Style::default()
                    .fg(Color::Black)
                    .bg(Color::Yellow)
                    .add_modifier(Modifier::BOLD),
            );
            frame.render_widget(paragraph, area);
            return;
        }
        let total_size = self.graph.nodes[ROOT].size;
        let processed_text = if self.scanning {
            let elapsed = self.traversal_started.elapsed();
            let seconds = elapsed.as_secs_f64();
            let rate = if seconds > 0.0 {
                (self.processed as f64 / seconds) as u64
            } else {
                0
            };
            format!(
                "Processed {} entries in {}s ({}/s)  -> scanning <-",
                self.processed,
                elapsed.as_secs(),
                rate
            )
        } else {
            format!(
                "Processed {} entries in {:.2}s",
                self.processed,
                self.traversal_elapsed.as_secs_f64()
            )
        };
        let left = format!(
            "Sort mode: {}  Total disk usage: {}  {}",
            self.sort_mode.label(),
            formatted_trimmed(self.walk_opts.format, total_size),
            processed_text
        );
        let mut spans = vec![Span::styled(
            left,
            Style::default().add_modifier(Modifier::REVERSED),
        )];
        if let Some(message) = &self.message {
            spans.push(Span::raw("  "));
            spans.push(Span::styled(
                message.clone(),
                Style::default()
                    .fg(Color::Red)
                    .add_modifier(Modifier::BOLD)
                    .add_modifier(Modifier::SLOW_BLINK),
            ));
        }
        frame.render_widget(Paragraph::new(Line::from(spans)), area);
    }
}

fn unicode_width_of(text: &str) -> usize {
    // A deliberately simple width calculation; the reference is also
    // documented to miscalculate widths for some grapheme clusters.
    text.chars()
        .map(|ch| if (ch as u32) < 0x1100 { 1 } else { 2 })
        .sum()
}

pub fn run(
    inputs: &[PathBuf],
    walk_opts: &WalkOptions,
    no_entry_check: bool,
) -> Result<i32, Box<dyn Error>> {
    let resolved = resolve_inputs(inputs, walk_opts)?;
    let mut app = App::new(resolved.root_display.clone(), walk_opts.clone(), no_entry_check);
    app.spawn_traversal(resolved.roots.clone());

    enable_raw_mode()?;
    let mut stdout: Stdout = io::stdout();
    if let Err(err) = execute!(stdout, EnterAlternateScreen) {
        let _ = disable_raw_mode();
        return Err(Box::new(err));
    }
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = match Terminal::new(backend) {
        Ok(terminal) => terminal,
        Err(err) => {
            let _ = disable_raw_mode();
            let _ = execute!(io::stdout(), LeaveAlternateScreen);
            return Err(Box::new(err));
        }
    };
    let _ = terminal.clear();

    let mut result: Result<i32, Box<dyn Error>> = Ok(0);
    loop {
        app.process_traversal_messages();
        if let Err(err) = terminal.draw(|frame| app.draw(frame)) {
            result = Err(Box::new(err));
            break;
        }
        if app.should_quit {
            break;
        }
        let timeout = if app.scanning {
            Duration::from_millis(20)
        } else {
            Duration::from_millis(250)
        };
        match event::poll(timeout) {
            Ok(true) => match event::read() {
                Ok(Event::Key(key)) => app.handle_key(key),
                Ok(_) => {}
                Err(err) => {
                    result = Err(Box::new(err));
                    break;
                }
            },
            Ok(false) => {}
            Err(err) => {
                result = Err(Box::new(err));
                break;
            }
        }
        if app.should_quit {
            break;
        }
    }

    let _ = terminal.show_cursor();
    let _ = disable_raw_mode();
    let _ = execute!(io::stdout(), LeaveAlternateScreen);
    result
}
