    let mut app = App::new(resolved.root_display.clone(), walk_opts.clone(), no_entry_check);
    app.spawn_traversal(resolved.roots.clone());

    enable_raw_mode()?;
    let mut stdout: Stdout = io::stdout();
    if let Err(err) = execute!(stdout, EnterAlternateScreen) {
        let _ = disable_raw_mode();
        return Err(Box::new(err));
    }
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = match Terminal::new(backend) {
        Ok(terminal) => terminal,
        Err(err) => {
            let _ = disable_raw_mode();
            let _ = execute!(io::stdout(), LeaveAlternateScreen);
            return Err(Box::new(err));
        }
    };
    let _ = terminal.clear();

    let mut result: Result<i32, Box<dyn Error>> = Ok(0);
    loop {
        app.process_traversal_messages();
        if let Err(err) = terminal.draw(|frame| app.draw(frame)) {
            result = Err(Box::new(err));
            break;
        }
        if app.should_quit {
            break;
        }
        let timeout = if app.scanning {
            Duration::from_millis(20)
        } else {
            Duration::from_millis(250)
        };
        match event::poll(timeout) {
            Ok(true) => match event::read() {
                Ok(Event::Key(key)) => app.handle_key(key),
                Ok(_) => {}
                Err(err) => {
                    result = Err(Box::new(err));
                    break;
                }
            },
            Ok(false) => {}
            Err(err) => {
                result = Err(Box::new(err));
                break;
            }
        }
        if app.should_quit {
            break;
        }
    }

    let _ = terminal.show_cursor();
    let _ = disable_raw_mode();
    let _ = execute!(io::stdout(), LeaveAlternateScreen);
    result
}
