p='src/interactive.rs';s=open(p).read()
start=s.index('    fn draw_scrollbar(')
end=s.index('    fn draw_help(',start)
new='''    fn draw_scrollbar(
        &self,
        frame: &mut Frame<'_>,
        area: Rect,
        content_length: usize,
        selected_index: Option<usize>,
        _viewport_height: u16,
    ) {
        if content_length == 0 || area.height < 3 || area.width == 0 {
            return;
        }
        let track_length = area.height.saturating_sub(2) as usize;
        if track_length == 0 {
            return;
        }
        let viewport_length = track_length;
        let max_position = content_length.saturating_sub(1);
        let position = selected_index.unwrap_or(0).min(max_position);
        let max_viewport_position = max_position + viewport_length;
        let rounding_divide = |numerator: usize, denominator: usize| {
            (numerator + denominator / 2) / denominator
        };
        let thumb_start = rounding_divide(position * track_length, max_viewport_position)
            .min(track_length - 1);
        let mut thumb_end = rounding_divide(
            (position + viewport_length) * track_length,
            max_viewport_position,
        )
        .min(track_length);
        if thumb_end <= thumb_start {
            thumb_end = (thumb_start + 1).min(track_length);
        }
        let focused = match self.active_pane {
            PaneKind::Main => area.x == 0 || !self.marked_visual_focus,
            _ => false,
        };
        let _ = focused;
        // The scrollbar inherits the border style of its pane.  The caller
        // renders it after the block, on the block's right border column.
        let x = area.x + area.width - 1;
        let buffer = frame.buffer_mut();
        // Determine the border style from an existing border cell so the
        // thumb/track match focused and unfocused panes alike.
        let style = buffer[(x, area.y)].style();
        for offset in 0..track_length {
            let y = area.y + 1 + offset as u16;
            let symbol = if offset >= thumb_start && offset < thumb_end {
                "█"
            } else {
                "║"
            };
            let cell = &mut buffer[(x, y)];
            cell.set_symbol(symbol);
            cell.set_style(style);
        }
    }

'''
