impl App {
    fn draw_bottom_title(&self, frame: &mut Frame<'_>, area: Rect, pane: PaneKind) {
        if !self.is_pane_visually_focused(pane) || area.width == 0 || area.height == 0 {
            return;
        }
        let text = match pane {
            PaneKind::Main => " mark-move = d | mark-toggle = space | toggle-all = a ",
            PaneKind::Marked => " mark-toggle = space,d | remove-all = a",
            _ => return,
        };
        let width = unicode_width_of(text);
        if width > area.width.saturating_sub(1) as usize {
            return;
        }
        let x = area.x + area.width - 1 - width as u16;
        let y = area.y + area.height - 1;
        let style = Style::default().add_modifier(Modifier::BOLD);
        frame.buffer_mut().set_string(x, y, text, style);
    }
}
