                    processed += 1;
                }
                if entry.depth == 0 {
                    got_root = true;
                }
                if !entry.io_error {
                    fresh.push(entry);
                }
            }
            WalkEvent::Error => {}
        });
        if !got_root {
            let parent = self.graph.nodes[root_node].parent;
            self.graph.remove_subtree(root_node);
            if self.current == root_node {
                self.current = parent.unwrap_or(ROOT);
                self.view_stack.clear();
            }
            return processed;
        }
        let old_subtree: HashSet<usize> = self.graph.subtree_ids(root_node).into_iter().collect();
        let mut matched: HashSet<usize> = HashSet::new();
        let mut stack: Vec<usize> = Vec::new();
        let mut new_children: HashMap<usize, Vec<usize>> = HashMap::new();
        for entry in &fresh {
            if entry.depth == 0 {
