                stack.push(root_node);
                new_children.entry(root_node).or_default();
                continue;
            }
            while stack.len() > entry.depth {
                stack.pop();
            }
            let Some(&parent) = stack.get(entry.depth - 1) else {
                continue;
            };
            let existing = self.graph.nodes[parent]
                .children
                .iter()
                .copied()
                .find(|id| {
                    !matched.contains(id)
                        && self.graph.is_alive(*id)
                        && self.graph.nodes[*id].name == entry.name
                });
            let id = if let Some(existing_id) = existing {
                let node = &mut self.graph.nodes[existing_id];
                node.own_size = entry.size;
                node.size = entry.size;
                node.count = 1;
                node.mtime = entry.mtime;
                node.is_dir = entry.is_dir;
                existing_id
            } else {
