            new_children.entry(id).or_default();
            if stack.len() == entry.depth {
                stack.push(id);
            } else if stack.len() > entry.depth {
                stack[entry.depth] = id;
                stack.truncate(entry.depth + 1);
            } else {
                stack.push(id);
            }
        }
        for (parent, children) in new_children {
            self.graph.nodes[parent].children = children;
        }
        for id in old_subtree {
            if !matched.contains(&id) {
                self.graph.nodes[id].alive = false;
                self.graph.nodes[id].children.clear();
            }
        }
        self.graph.recompute();
        processed
    }

    fn finish_refresh(&mut self, processed: u64, started: Instant) {
        self.marked.retain(|item| self.graph.is_alive(item.node));
        self.sync_marked_selection();
        self.processed = processed;
        self.traversal_elapsed = started.elapsed();
        self.refresh_checked_dirs();
        self.ensure_selection();
