                processed += self.refresh_with_walk(node_id, true, &mut seen);
            }
        }
        self.finish_refresh(processed, started);
    }

    fn refresh_current(&mut self) {
        let started = Instant::now();
        let mut seen: HashSet<(u64, u64)> = HashSet::new();
        let processed = self.refresh_with_walk(self.current, false, &mut seen);
        self.finish_refresh(processed, started);
    }

