fn truncate_start(text: &str, max_width: usize) -> String {
    use unicode_segmentation::UnicodeSegmentation;
    use unicode_width::UnicodeWidthChar;
    if unicode_width_of(text) <= max_width {
        return text.to_string();
    }
    if max_width <= 1 {
        return "…".to_string();
    }
    let suffix_width = max_width - 1;
    let grapheme_width = |g: &str| -> usize {
        g.chars()
            .map(|ch| UnicodeWidthChar::width(ch).unwrap_or(0))
            .sum()
    };
    let mut suffix = String::new();
    let mut width = 0usize;
    for grapheme in text.graphemes(true).rev() {
        let grapheme_width = grapheme_width(grapheme);
        if width + grapheme_width > suffix_width {
            break;
        }
        suffix.insert_str(0, grapheme);
        width += grapheme_width;
    }
    format!("…{}", suffix)
}
