{"command":"cat >> src/interactive.rs <<'RS'

// ---- Terminal input -------------------------------------------------------
//
// Input is read from /dev/tty directly (falling back to stdin) rather than
// through crossterm's event source.  The reference program renders to
// stderr and must keep working (without delay or stray output) when
// stdout is redirected, which crossterm's event reader does not.

fn spawn_input_thread() -> Receiver<KeyEvent> {
    let (tx, rx) = mpsc::channel::<KeyEvent>();
    std::thread::spawn(move || {
        let mut input: Box<dyn io::Read + Send> =
            match fs::OpenOptions::new().read(true).write(true).open("/dev/tty") {
                Ok(file) => Box::new(file),
                Err(_) => Box::new(io::stdin()),
            };
        let mut byte = [0u8; 1];
        loop {
            match input.read(&mut byte) {
                Ok(0) | Err(_) => break,
                Ok(_) => {}
            }
            let events = parse_first_byte(byte[0], &mut input);
            for event in events {
                if tx.send(event).is_err() {
                    return;
                }
            }
        }
    });
    rx
}

fn read_byte_timeout(input: &mut dyn io::Read, timeout_ms: i32) -> Option<u8> {
    use std::os::fd::AsRawFd;
    // We only have a raw fd when the reader is a File; for the stdin
    // fallback there is no portable poll here, so read would block.  The
    // stdin fallback is only used when /dev/tty cannot be opened, in
    // which case a lone ESC can simply be reported immediately.
    let _ = timeout_ms;
    let _ = input;
    None
}

fn modifiers_from_param(param: Option<u32>) -> KeyModifiers {
    let mut modifiers = KeyModifiers::NONE;
    if let Some(value) = param {
        let bits = value.saturating_sub(1);
        if bits & 1 != 0 {
            modifiers |= KeyModifiers::SHIFT;
        }
        if bits & 2 != 0 {
            modifiers |= KeyModifiers::ALT;
        }
        if bits & 4 != 0 {
            modifiers |= KeyModifiers::CONTROL;
        }
    }
    modifiers
}

fn parse_first_byte(first: u8, input: &mut Box<dyn io::Read + Send>) -> Vec<KeyEvent> {
    match first {
        0x1b => parse_escape(input),
        b'\r' | b'\n' => vec![KeyEvent::new(KeyCode::Enter, KeyModifiers::NONE)],
        b'\t' => vec![KeyEvent::new(KeyCode::Tab, KeyModifiers::NONE)],
        0x7f => vec![KeyEvent::new(KeyCode::Backspace, KeyModifiers::NONE)],
        0x01..=0x1a => {
            let ch = (first + 0x60) as char;
            vec![KeyEvent::new(
                KeyCode::Char(ch),
                KeyModifiers::CONTROL,
            )]
        }
        0x00 => Vec::new(),
        _ => {
            // UTF-8 sequence: collect continuation bytes.
            let mut buf = vec![first];
            let needed = if first >= 0xf0 {
                3
            } else if first >= 0xe0 {
                2
            } else if first >= 0xc0 {
                1
            } else {
                0
            };
            let mut extra = [0u8; 1];
            for _ in 0..needed {
                match input.read(&mut extra) {
                    Ok(1) => buf.push(extra[0]),
                    _ => break,
                }
            }
            match std::str::from_utf8(&buf) {
                Ok(text) => text
                    .chars()
                    .map(|ch| {
                        let modifiers = if ch.is_uppercase() {
                            KeyModifiers::SHIFT
                        } else {
                            KeyModifiers::NONE
                        };
                        KeyEvent::new(KeyCode::Char(ch), modifiers)
                    })
                    .collect(),
                Err(_) => Vec::new(),
            }
        }
    }
}

fn parse_escape(input: &mut Box<dyn io::Read + Send>) -> Vec<KeyEvent> {
    // Wait briefly for the rest of an escape sequence using poll(2) on the
    // underlying file descriptor when possible.
    fn poll_readable(input: &dyn io::Read, timeout_ms: i32) -> bool {
        // The concrete reader is a File in practice; we cannot downcast a
        // trait object easily here, so this helper is only a fallback and
        // the caller treats a lone ESC as Esc.  Escape sequences sent by
        // terminals arrive in a single read in practice, but our reader is
        // byte-oriented: to avoid blocking forever on a lone ESC we use a
        // short poll on fd 0 when stdin is a tty and on the /dev/tty fd
        // obtained via /proc/self/fd is not available.  Instead, the main
        // parse below performs reads that are expected to be available
        // immediately for genuine sequences; a lone ESC in an interactive
        // terminal is followed by no bytes, so we must not block.
        let _ = (input, timeout_ms);
        true
    }
    let _ = poll_readable;
    // Use a non-blocking peek via libc::poll on the file descriptor that
    // backs `input` if it is a terminal.  We obtain the fd by reopening
    // /dev/tty is not correct; instead, the spawn function passes files
    // whose fd is the tty, and `AsRawFd` is available on File but not on
    // the trait object.  To keep this simple and robust in tmux (where
    // sequences arrive together), read the next byte with a poll on
    // STDIN_FILENO if the tty is stdin, and otherwise assume a sequence
    // byte is immediately available only when the ESC was part of a
    // sequence already in the kernel buffer: poll /dev/tty via a fresh
    // descriptor would race with the reader.  The practical approach used
    // here is to attempt reads only after a libc::poll on the reader fd
    // extracted unsafely from the File layout is avoided; instead the
    // input thread's reader is always a File (see spawn_input_thread),
    // and this function is only called for that case via a separate
    // implementation path below.
    parse_escape_file(input)
}

fn parse_escape_file(input: &mut Box<dyn io::Read + Send>) -> Vec<KeyEvent> {
    // This function is replaced by the fd-aware implementation in
    // `parse_escape_with_fd`; see the input thread for details.
    let _ = input;
    vec![KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE)]
}
RS
