            Some(b'F') => vec![KeyEvent::new(KeyCode::End, KeyModifiers::NONE)],
            _ => Vec::new(),
        },
        0x1b => {
            // A second ESC: report the first, then treat the second as a
            // new escape introducer.
            let mut events = vec![KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE)];
            events.extend(parse_escape(input));
            events
        }
        _ => {
            // Alt+character (or an unsupported sequence byte).
            if second.is_ascii_graphic() {
                vec![KeyEvent::new(
                    KeyCode::Char(second as char),
                    KeyModifiers::ALT,
                )]
            } else {
                vec![KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE)]
            }
        }
    }
}

fn parse_csi(input: &mut InputSource) -> Vec<KeyEvent> {
    let mut params: Vec<u8> = Vec::new();
    let final_byte;
    loop {
        match read_byte_timeout(input, 10) {
            Some(byte) if (0x40..=0x7e).contains(&byte) => {
                final_byte = byte;
                break;
            }
            Some(byte) => params.push(byte),
            None => return vec![KeyEvent::new(KeyCode::Esc, KeyModifiers::NONE)],
        }
    }
    let param_text = String::from_utf8_lossy(&params).into_owned();
    let mut numbers = param_text
        .trim_start_matches(['<', '?'])
        .split(';')
        .map(|part| part.parse::<u32>().ok());
    let first = numbers.next().flatten();
    let second = numbers.next().flatten();
    let modifiers = modifiers_from_param(second);
    let code = match final_byte {
        b'A' => Some(KeyCode::Up),
        b'B' => Some(KeyCode::Down),
        b'C' => Some(KeyCode::Right),
        b'D' => Some(KeyCode::Left),
        b'H' => Some(KeyCode::Home),
        b'F' => Some(KeyCode::End),
        b'Z' => return vec![KeyEvent::new(KeyCode::BackTab, KeyModifiers::SHIFT)],
        b'~' => match first {
            Some(2) => Some(KeyCode::Insert),
            Some(3) => Some(KeyCode::Delete),
            Some(5) => Some(KeyCode::PageUp),
            Some(6) => Some(KeyCode::PageDown),
            Some(1 | 7) => Some(KeyCode::Home),
            Some(4 | 8) => Some(KeyCode::End),
            Some(11) => Some(KeyCode::F(1)),
            Some(12) => Some(KeyCode::F(2)),
            Some(13) => Some(KeyCode::F(3)),
            Some(14) => Some(KeyCode::F(4)),
            Some(15) => Some(KeyCode::F(5)),
            Some(17) => Some(KeyCode::F(6)),
            Some(18) => Some(KeyCode::F(7)),
            Some(19) => Some(KeyCode::F(8)),
            Some(20) => Some(KeyCode::F(9)),
            Some(21) => Some(KeyCode::F(10)),
            Some(23) => Some(KeyCode::F(11)),
            Some(24) => Some(KeyCode::F(12)),
            _ => None,
        },
        b'u' => first
            .and_then(char::from_u32)
            .map(KeyCode::Char),
        _ => None,
    };
    match code {
        Some(code) => vec![KeyEvent::new(code, modifiers)],
        None => Vec::new(),
    }
}
RS
"}

